import {asset, versioned} from "./api";
import {
    RSC_BLACK,
    RSC_OVERHEAD_COLOR,
    randomRscColor,
    tokenizeRscMarkup,
} from "./rscMarkup";
/**
 * The game's bitmap font (h12b — font 1, bold 12px) + the stock overhead-chat
 * text renderer, both ported from the client:
 *
 * - Glyphs come from the baked white-on-transparent atlas
 *   (/api/world3d/font-h12b.{png,json}); tinting happens here per colour.
 * - Wrapping is GraphicsController.drawWrappedCenteredString: advance widths
 *   accumulate (skipping @col@ / ~1234~ codes), break at the last space once
 *   a line exceeds 300px, first line at the anchor baseline, later lines
 *   below (y += lineHeight).
 * - Drawing is drawstring: black drop shadow at (+1,0) and (0,+1) under each
 *   glyph (all game fonts are non-antialiased), colour switches on @col@
 *   codes and carries across wrapped lines (S_WANT_FIXED_OVERHEAD_CHAT).
 *   The markup scanner itself is shared with the DOM chat panel — see
 *   ./rscMarkup.
 */

export interface Glyph {
    x: number;
    y: number;
    w: number;
    h: number;
    xo: number;
    yo: number;
    adv: number;
}

export class GameFont {
    readonly lineHeight: number;
    /** Glyph top extent above / below the baseline, over the whole face. */
    readonly ascent: number;
    readonly descent: number;
    private readonly glyphs = new Map<number, Glyph>();
    private readonly fallback: Glyph;
    private readonly atlas: HTMLImageElement;
    private readonly tinted = new Map<string, HTMLCanvasElement>();

    constructor(atlas: HTMLImageElement,
                idx: {lineHeight: number; chars: Glyph[] & {c?: number}[]}) {
        this.atlas = atlas;
        this.lineHeight = idx.lineHeight;
        let asc = 1;
        let desc = 1;
        for (const c of idx.chars as (Glyph & {c: number})[]) {
            this.glyphs.set(c.c, c);
            asc = Math.max(asc, c.yo);
            desc = Math.max(desc, c.h - c.yo);
        }
        this.ascent = asc;
        this.descent = desc;
        // The client maps unknown chars to charset index 74 ('=').
        this.fallback = this.glyphs.get(61)!;
    }

    glyph(code: number): Glyph {
        return this.glyphs.get(code) ?? this.fallback;
    }

    /** Whole-atlas copy filled with `color` (glyphs are a pure alpha mask). */
    private tintedAtlas(color: string): HTMLCanvasElement {
        let c = this.tinted.get(color);
        if (!c) {
            // The fixed palette is 31 colours, so this only ever grows under
            // @ran@ — which rolls a fresh colour EVERY frame it is on screen.
            // Drop the lot rather than leak one atlas per roll; the handful of
            // palette entries in flight re-tint on the next frame.
            if (this.tinted.size > 64) this.tinted.clear();
            c = document.createElement("canvas");
            c.width = this.atlas.width;
            c.height = this.atlas.height;
            const g = c.getContext("2d")!;
            g.drawImage(this.atlas, 0, 0);
            g.globalCompositeOperation = "source-in";
            g.fillStyle = color;
            g.fillRect(0, 0, c.width, c.height);
            this.tinted.set(color, c);
        }
        return c;
    }

    /** Advance width of a string, skipping @col@ / ~1234~ codes (stringWidth). */
    width(str: string): number {
        let w = 0;
        for (let i = 0; i < str.length; i++) {
            if (str[i] === "@" && i + 4 < str.length && str[i + 4] === "@") {
                i += 4;
            } else if (str[i] === "~" && i + 4 < str.length && str[i + 4] === "~") {
                i += 4;
            } else {
                w += this.glyph(str.charCodeAt(i)).adv;
            }
        }
        return w;
    }

    /**
     * Stock wrap (drawWrappedCenteredString, wrapWidth 300): returns the
     * substrings drawn per line, colour codes left in place.
     */
    wrap(str: string, wrapWidth: number): string[] {
        const lines: string[] = [];
        let width = 0;
        let lastLineTerm = 0;
        let lastBreak = 0;
        for (let i = 0; i < str.length; i++) {
            if (str[i] === "@" && i + 4 < str.length && str[i + 4] === "@") {
                i += 4;
            } else if (str[i] === "~" && i + 4 < str.length && str[i + 4] === "~") {
                i += 4;
            } else {
                width += this.glyph(str.charCodeAt(i)).adv;
            }
            if (str[i] === " ") {
                lastBreak = i;
            }
            if (width > wrapWidth) {
                let lineEndsAt = lastBreak;
                if (lastBreak <= lastLineTerm) {
                    lineEndsAt = lastBreak = i;
                }
                lines.push(str.substring(lastLineTerm, lineEndsAt));
                lastLineTerm = i = 1 + lastBreak;
                width = 0;
            }
        }
        if (width > 0) {
            lines.push(str.substring(lastLineTerm));
        }
        return lines;
    }

    /**
     * Render wrapped overhead text into a canvas: each line centred, the
     * stock shadow + colour handling, default colour = overhead yellow.
     * Returns the canvas plus where the FIRST line's baseline and the centre
     * axis sit inside it (in LOGICAL px), so the caller can pin it to the
     * stock anchor (sprite mid-x, sprite top).
     *
     * `scale` supersamples the backing store (pass ceil(devicePixelRatio));
     * the canvas is CSS-sized to logical px, so glyph pixels land on (or
     * uniformly resample to) the device grid instead of warping — a 1:1
     * canvas at fractional positions/DPR gets nearest-neighbour column
     * drops that read as slanted "italic" text.
     *
     * Pass the previous canvas as `into` to redraw in place (setting width
     * clears it), which is what an `@ran@` line needs — it re-rolls its
     * colour every frame, and swapping a fresh canvas into the DOM that
     * often is pure churn.
     *
     * `animated` in the result means the string contains an `@ran@`, i.e.
     * this render is only valid for one frame.
     */
    renderOverhead(str: string, wrapWidth = 300,
                   defaultColor = RSC_OVERHEAD_COLOR,
                   scale = 1, into?: HTMLCanvasElement | null):
        {canvas: HTMLCanvasElement; baseline: number; midX: number;
         width: number; height: number; animated: boolean;
         totalWidth: number; extraLinesHeight: number} {
        const r = this.draw(str, {wrapWidth, defaultColor, scale, into});
        // Stock bubble-collision metrics: halfWidth = stringWidth/2 (cap 150),
        // height = (stringWidth/300|0) * lineHeight — from the UNWRAPPED width.
        const totalWidth = this.width(str);
        return {canvas: r.canvas, baseline: this.ascent, midX: r.width / 2,
            width: r.width, height: r.height, animated: r.animated,
            totalWidth,
            extraLinesHeight: Math.floor(totalWidth / wrapWidth) * this.lineHeight};
    }

    /**
     * The glyph loop — a port of drawstring, laying wrapped lines down a
     * canvas, each centred on the bubble's axis at one lineHeight apart.
     *
     * The canvas is sized to hold the ink: the widest line plus 1px for the
     * shadow's rightward spill, and `(lines-1)*pitch` plus the face's full
     * ascent/descent plus 1px for its downward spill.
     */
    private draw(str: string, opts: {
        wrapWidth: number; defaultColor: string; scale: number;
        into?: HTMLCanvasElement | null;
    }): {canvas: HTMLCanvasElement; width: number; height: number;
         lines: number; animated: boolean} {
        const lines = this.wrap(str, opts.wrapWidth);
        const widths = lines.map(l => this.width(l));
        const maxW = Math.max(1, ...widths);
        const logicalW = maxW + 1;               // +1: shadow spills right
        const logicalH = (lines.length - 1) * this.lineHeight
            + this.ascent + this.descent + 1;    // +1: shadow spills down
        const canvas = opts.into ?? document.createElement("canvas");
        // Assigning either dimension resets the bitmap — that IS the clear
        // when we are redrawing into a canvas the caller handed back.
        canvas.width = logicalW * opts.scale;
        canvas.height = logicalH * opts.scale;
        canvas.style.width = `${logicalW}px`;
        canvas.style.height = `${logicalH}px`;
        const g = canvas.getContext("2d")!;
        g.imageSmoothingEnabled = false;
        g.setTransform(opts.scale, 0, 0, opts.scale, 0, 0);
        let color = opts.defaultColor;
        let animated = false;
        for (let li = 0; li < lines.length; li++) {
            const baseY = this.ascent + li * this.lineHeight;
            let x = Math.floor((maxW - widths[li]) / 2);
            // Colour is NOT reset per line: it carries across the wrap, which
            // is what S_WANT_FIXED_OVERHEAD_CHAT re-injects into each line the
            // stock wrapper hands to drawstring (and what rsc-c's own wrap
            // does by re-emitting the last code on the continuation).
            for (const tok of tokenizeRscMarkup(lines[li])) {
                if (tok.kind === "color") {
                    color = tok.color;
                    continue;
                }
                if (tok.kind === "random") {
                    color = randomRscColor();
                    animated = true;
                    continue;
                }
                if (tok.kind === "cursor") {
                    // Consumed, not applied: stock's ~ddd~ moves the pen to an
                    // absolute SCREEN x, while this canvas has its own origin
                    // — and stringWidth (which sized it) ignores the code too,
                    // so honouring it here alone would push glyphs outside the
                    // measured box. No Uranium string uses one.
                    continue;
                }
                // drawstring skips the shadow when the colour is black.
                const shadow = color === RSC_BLACK ? null : this.tintedAtlas(RSC_BLACK);
                const face = this.tintedAtlas(color);
                for (let i = 0; i < tok.text.length; i++) {
                    const gl = this.glyph(tok.text.charCodeAt(i));
                    if (gl.w > 0 && gl.h > 0) {
                        const dx = x + gl.xo;
                        const dy = baseY - gl.yo;
                        if (shadow) {
                            // drawstring: black at (+1,0) and (0,+1), colour on top.
                            g.drawImage(shadow, gl.x, gl.y, gl.w, gl.h,
                                dx + 1, dy, gl.w, gl.h);
                            g.drawImage(shadow, gl.x, gl.y, gl.w, gl.h,
                                dx, dy + 1, gl.w, gl.h);
                        }
                        g.drawImage(face, gl.x, gl.y, gl.w, gl.h,
                            dx, dy, gl.w, gl.h);
                    }
                    x += gl.adv;
                }
            }
        }
        return {canvas, width: logicalW, height: logicalH,
            lines: lines.length, animated};
    }
}

/** Fetch the baked h12b atlas + metrics; rejects when the bake isn't ready. */
export function loadGameFont(): Promise<GameFont> {
    return versioned("/api/world3d/font-h12b.json")
        .then(url => fetch(url))
        .then(r => {
            if (!r.ok) throw new Error(`font index ${r.status}`);
            return r.json();
        })
        .then(idx => new Promise<GameFont>((res, rej) => {
            const img = new Image();
            img.onload = () => res(new GameFont(img, idx));
            img.onerror = rej;
            // ?v= from the index's own bake stamp: the json is served no-cache
            // but the png `max-age=7d`, so an unversioned png outlives a rebake
            // and gets sliced with the new glyph rectangles.
            img.src = asset(`/api/world3d/font-h12b.png?v=${idx.baked}`);
        }));
}
