import {RIBBON_HALF_WIDTH, type Ribbon} from "./World3DSight";
import {drapeGate} from "./World3DOverlays";
import type {OverlayContext, ViewerOverlay} from "./World3DOverlays";

/**
 * The route and trail ribbons, as overlays.
 *
 * They are the view's own decoration, built on the same interface an embedder gets — which is the
 * point. An extension point nothing internal uses is a guess about what an extension needs; this
 * one carries two shipped features, so the context is known to be enough to drape a line on
 * terrain, follow a floor switch, and redrape when the ground settles.
 */

export interface PathPoint {
    x: number;
    /** ABSOLUTE z — floor folded in, as it arrives from the server. */
    z: number;
    /** Route only: this step is a jump (transport, ladder, teleport), not a walk. */
    hop?: boolean;
}

export interface PathStyle {
    color: number;
    opacity: number;
    ghostOpacity: number;
    /**
     * Break the line where consecutive points are more than this many tiles apart. A walk covers
     * one tile per tick, so a bigger gap is a teleport and drawing through it would trace a line
     * across country nobody walked. Omit when the data flags its own jumps.
     */
    breakOverTiles?: number;
    /** Drop repeats of the same tile before draping. A per-tick feed stands still a lot, and a
     *  zero-length segment has no direction to miter. */
    dropRepeats?: boolean;
    /**
     * Draw the line dotted: `on` tiles of ribbon, then `off` tiles of nothing, along each chain.
     * The chain is cut into dashes in tile space before draping, so every dash still follows the
     * terrain. What tells the engine's own route (a sparse polyline through seam spans) from the
     * walk that was simulated over it.
     */
    dash?: {on: number; off: number};
    /** The narrowest the line may draw on screen, in pixels: zoomed out, the ribbon widens to
     *  keep it. Default {@link MIN_PATH_PX}. */
    minPx?: number;
}

/** A path stays at least this wide on screen, however far out the view zooms. */
export const MIN_PATH_PX = 2;
/** A dash (and the gap after it) stays at least this long on screen. */
const MIN_DASH_PX = 6;

/**
 * The factor that keeps `px` screen pixels at least `tiles` long at this zoom — 1 when it already
 * is — in half-octave steps, so a zoom redrapes the line a handful of times rather than every frame.
 */
function screenFloor(ctx: OverlayContext, px: number, tiles: number): number {
    const want = px * ctx.zoomTiles / Math.max(1, ctx.view.h) / tiles;
    if (!(want > 1)) return 1;
    return Math.SQRT2 ** Math.ceil(Math.log2(want) * 2);
}

/** Distances closer than this are the same point: a dash edge within it of the walk is reached. */
const DASH_EPS = 1e-6;

/**
 * {@code chain} cut into dashes of `on` tiles every `on + off` tiles along its length.
 *
 * Every dash edge is computed from its index — `k * period` and `k * period + on` — against the
 * distance along the whole chain, never by adding step lengths up. The accumulated version hung
 * the tab: at a non-integer zoom scale (√2) the running sum drifted until an edge sat a rounding
 * error ahead of it, the step to it no longer changed the sum, and `frame` never returned
 * (2026-09-17, a long planned route viewed zoomed out). The loop is also capped at the number of
 * edges the chain can hold, so no input can spin it.
 */
export function dashed(chain: {x: number; z: number}[], on: number, off: number):
    {pts: {x: number; z: number}[]; closed: boolean}[] {
    const out: {pts: {x: number; z: number}[]; closed: boolean}[] = [];
    const period = on + off;
    if (!(on > 0) || !(period > 0) || chain.length < 2) return out;
    let total = 0;
    for (let i = 0; i + 1 < chain.length; i++) {
        total += Math.hypot(chain[i + 1].x - chain[i].x, chain[i + 1].z - chain[i].z);
    }
    let budget = 2 * Math.ceil(total / Math.min(on, off > 0 ? off : on)) + 2 * chain.length + 16;
    let base = 0; // distance along the chain to the start of the current segment
    let cur: {x: number; z: number}[] = [];
    const flush = () => {
        if (cur.length > 1) out.push({pts: cur, closed: false});
        cur = [];
    };
    for (let i = 0; i + 1 < chain.length; i++) {
        const a = chain[i];
        const b = chain[i + 1];
        const len = Math.hypot(b.x - a.x, b.z - a.z);
        if (len === 0) continue;
        const at = (t: number) => ({x: a.x + (b.x - a.x) * (t / len), z: a.z + (b.z - a.z) * (t / len)});
        let t = 0;
        while (len - t > DASH_EPS && budget-- > 0) {
            const g = base + t;
            let k = Math.floor(g / period);
            // A point a rounding error short of the next period's start is at it.
            if ((k + 1) * period - g <= DASH_EPS) k++;
            const onEnd = k * period + on;
            const drawing = onEnd - g > DASH_EPS;
            const edge = drawing ? onEnd : (k + 1) * period;
            const next = Math.min(len, edge - base);
            if (drawing) {
                if (cur.length === 0) cur.push(at(t));
                cur.push(at(next));
            } else {
                flush();
            }
            t = next > t ? next : len; // an edge that is no step ahead ends the segment
        }
        base += len;
    }
    flush();
    return out;
}

/**
 * One draped polyline, broken at floor changes and at jumps.
 *
 * Rebuilt only when its data, floor or the settled terrain changes — `frame` runs every frame, and
 * re-extruding a thousand-point trail at 60 Hz for a line that hasn't moved is exactly the kind of
 * work the dirty check exists to skip.
 */
export function pathOverlay(style: PathStyle): ViewerOverlay<PathPoint[] | null | undefined> {
    let ribbon: Ribbon | null = null;
    const stale = drapeGate();
    let lastWidth = 0;
    let lastDash = 0;
    return {
        mount(ctx: OverlayContext) {
            ribbon = ctx.ribbon({
                color: style.color, opacity: style.opacity,
                ghostOpacity: style.ghostOpacity, band: "ground",
            });
        },
        frame(ctx: OverlayContext, data) {
            const width = screenFloor(ctx, style.minPx ?? MIN_PATH_PX, 2 * RIBBON_HALF_WIDTH);
            const dashScale = style.dash ? screenFloor(ctx, MIN_DASH_PX, style.dash.on) : 1;
            // Always asked: the gate must see each frame's data to stay current.
            const moved = stale(ctx, data);
            if (!moved && width === lastWidth && dashScale === lastDash) return;
            lastWidth = width;
            lastDash = dashScale;
            const chains: {pts: {x: number; z: number}[]; closed: boolean}[] = [];
            let cur: {x: number; z: number}[] = [];
            let prev: PathPoint | null = null;
            for (const p of data ?? []) {
                if (style.dropRepeats && prev && p.x === prev.x && p.z === prev.z) continue;
                const onFloor = Math.floor(p.z / 944) === ctx.floor;
                const jump = p.hop === true
                    || (style.breakOverTiles != null && prev != null
                        && Math.max(Math.abs(p.x - prev.x), Math.abs(p.z - prev.z))
                            > style.breakOverTiles);
                if (jump || !onFloor) {
                    if (cur.length > 1) chains.push({pts: cur, closed: false});
                    cur = [];
                }
                if (onFloor) cur.push({x: p.x, z: p.z});
                prev = p;
            }
            if (cur.length > 1) chains.push({pts: cur, closed: false});
            const dash = style.dash;
            ribbon?.extrude(dash
                ? chains.flatMap(c => dashed(c.pts, dash.on * dashScale, dash.off * dashScale))
                : chains, ctx.toWorld, RIBBON_HALF_WIDTH * width);
        },
    };
}

/** The selected observer's planned route — blue, broken at transport hops. */
export const routeOverlay = pathOverlay({
    color: 0x4da3ff, opacity: 0.6, ghostOpacity: 0.16,
});

/** The engine's own route for the planner's trip — magenta and dotted, so it reads apart from the
 *  blue walk simulated over it: where the two differ is where the walker overrode the field. */
export const planOverlay = pathOverlay({
    color: 0xff6ad5, opacity: 0.85, ghostOpacity: 0.2,
    dash: {on: 1.5, off: 1.5},
});

/** The walk a plan predicted from its start tile — simulated with nothing in the way — kept beside
 *  the bot's own blue line while it walks, so where berthing and the like pull it off the
 *  prediction shows. Green and fainter, under the other two. */
export const predictedOverlay = pathOverlay({
    color: 0x5fe39a, opacity: 0.45, ghostOpacity: 0.12,
});

/** A recorded session's walked trail — amber, with teleports inferred from the gaps. */
export const trailOverlay = pathOverlay({
    color: 0xe8a33d, opacity: 0.7, ghostOpacity: 0.14,
    breakOverTiles: 5, dropRepeats: true,
});
