/**
 * Open-source demo entry. With "simulation" on, the page plays the server: every NPC spawn roams
 * its box, aggroes, chases and fights by the stock server's rules (sim/demoServer.ts), with a few
 * players wandering Lumbridge. Untick it to drop them and see the raw /api/world/npc-spawns.json
 * spawn ghosts. No live server — the world comes from the snapshot the bake wrote.
 *
 * The route planner runs in the page too: the pathfinder compiled to WebAssembly, in a worker, over
 * that snapshot (/api/nav/). The worker is the bot: with a plan found and the simulation running, a
 * route bot walks it, told each tick what it sees and answering what it sends, as a live bot is.
 */

/** A labelled tile box for the region overlay below. z is ABSOLUTE, as everything crossing the
 *  view's boundary is. */
interface Region {
    id: string;
    name: string;
    x0: number;
    z0: number;
    x1: number;
    z1: number;
}

/**
 * A worked example of the overlay API: draped boxes with a label, highlighting under the cursor,
 * and a click on the LABEL rather than the box — a box is a large click target and swallowing
 * clicks over it would eat the ground under it.
 *
 * Everything it needs comes from the context: a ribbon per region, one pooled label layer, the
 * tile→world transform, and the settled-terrain revision that says when to redrape.
 */
function regionOverlay(onSelect: (id: string) => void): ViewerOverlay<Region[]> {
    const ribbons = new Map<string, Ribbon>();
    let labels: TagPool | null = null;
    let hovered: string | null = null;
    // `frame` runs every frame; this says when a redrape is actually owed — the regions changed,
    // the floor changed, or the terrain under them settled at a new shape.
    const stale = drapeGate();
    const restyle = (ribbon: Ribbon, id: string) => (id === hovered
        ? ribbon.setStyle(0x7ee3ff, 0.95, 0.34)
        : ribbon.setStyle(0x7ee3ff, 0.5, 0.18));
    return {
        mount(ctx: OverlayContext) {
            labels = ctx.tags({
                css: "font:600 10px monospace;color:#7ee3ff;background:rgba(10,24,32,.8);"
                    + "padding:1px 5px;border:1px solid rgba(126,227,255,.5);border-radius:4px;",
                band: "chrome",
                interactive: true,
            });
            labels.onClick = key => onSelect(key);
        },
        frame(ctx: OverlayContext, regions: Region[]) {
            const redrape = stale(ctx, regions);
            for (const r of regions) {
                let ribbon = ribbons.get(r.id);
                if (!ribbon) {
                    ribbon = ctx.ribbon({color: 0x7ee3ff, opacity: 0.5, ghostOpacity: 0.18});
                    ribbons.set(r.id, ribbon);
                }
                if (redrape) {
                    // Per-tile, not four corners: extrude runs a straight line between the points
                    // it is given, and terrain corners move under every one of them.
                    ribbon.extrude([{pts: boxPerimeter(r), closed: true}], ctx.toWorld);
                }
            }
            labels?.begin(ctx.view, ctx.camera);
            for (const r of regions) {
                if (Math.floor(r.z0 / 944) !== ctx.floor) continue;
                labels?.put(r.id, ctx.toWorld((r.x0 + r.x1) / 2, (r.z0 + r.z1) / 2), r.name);
            }
            labels?.end();
        },
        hitTest(at: OverlayPoint, regions: Region[]): string | null {
            for (const r of regions) {
                if (at.x >= r.x0 && at.x <= r.x1 && at.z >= r.z0 && at.z <= r.z1) {
                    return r.id;
                }
            }
            return null;
        },
        hover(hit: string | null) {
            hovered = hit;
            for (const [id, ribbon] of ribbons) restyle(ribbon, id);
        },
    };
}

const DEMO_REGIONS: Region[] = [
    {id: "swamp", name: "Lumbridge swamp", x0: 108, z0: 680, x1: 140, z1: 700},
];

/** Stable empty references: with the simulation off there is nothing alive, so World3DView draws
 *  every spawn as a ghost instead. */
const NO_OBSERVERS: Observer[] = [];
const NOTHING_ALIVE: WorldEntities = {
    npcs: [], players: [], objects: [], wallObjects: [], groundItems: [],
};

/** The route bot's name, which is what the camera follows it by. */
const ROUTE_BOT = "route bot";

/** The server's tick. */
const TICK_MS = 640;
/** The simulation speeds the toolbar cycles through. */
const SPEEDS = [1, 2, 4, 8, 16];

/** A query parameter as the page was opened with. */
function urlParam(key: string): string | null {
    return new URLSearchParams(location.search).get(key);
}

/** Set (or with null, remove) one query parameter, leaving the others and the history as they are. */
function writeUrlParam(key: string, value: string | null): void {
    const p = new URLSearchParams(location.search);
    if (value == null) p.delete(key);
    else p.set(key, value);
    history.replaceState(null, "", `${location.pathname}?${p}${location.hash}`);
}

function Demo({names}: {names: Record<number, string>}) {
    // "Simulation" = the living world: NPCs, demo players and the route bot. On by default; when
    // off we feed no observers and only the /api/world/npc-spawns.json ghosts remain.
    // Kept in `?sim=0` when off.
    const [simulation, setSimulationState] = useState(() => urlParam("sim") !== "0");
    const setSimulation = (on: boolean) => {
        setSimulationState(on);
        writeUrlParam("sim", on ? null : "0");
    };
    // The camera on the route bot (`?follow=1`); a pan lets go of it.
    const [follow, setFollowState] = useState(() => urlParam("follow") === "1");
    const setFollow = (on: boolean) => {
        setFollowState(on);
        writeUrlParam("follow", on ? "1" : null);
    };
    const [danger, setDangerState] = useState(() => urlParam("danger") === "1");
    const setDanger = (on: boolean) => {
        setDangerState(on);
        writeUrlParam("danger", on ? "1" : null);
    };
    // The view reports picks; holding them is this app's job, which is the embedding contract.
    const [picked, setPicked] = useState<PickedEntity | null>(null);
    // The overlay implementation is STABLE and its data is per-render — that split is what keeps a
    // fresh `overlays` array every render from remounting anything.
    const regions = useMemo(() => regionOverlay(id => setPicked({
        kind: "region", name: DEMO_REGIONS.find(r => r.id === id)?.name ?? id,
        npcId: null, inCombat: false,
    })), []);
    const view = useRef<World3DHandle>(null);
    const routeEnds = useMemo(() => routeEndsOverlay(944), []);
    // How fast the simulation plays: 1x is the server's tick, faster divides it. NPCs and the route
    // bot run on this one clock. Kept in `?speed=` (absent at 1x).
    const [speed, setSpeedState] = useState(() => {
        const v = Number(urlParam("speed"));
        return SPEEDS.includes(v) ? v : 1;
    });
    const nextSpeed = () => {
        const v = SPEEDS[(SPEEDS.indexOf(speed) + 1) % SPEEDS.length];
        setSpeedState(v);
        writeUrlParam("speed", v === 1 ? null : String(v));
    };
    const tickMs = TICK_MS / speed;
    const [plannerOpen, setPlannerOpen] = useState(false);
    // One worker for the page's life, started when first wanted: the simulation needs the world,
    // the planner the pathfinder over it.
    const host = useNavHost(simulation || plannerOpen);
    const planner = useDemoPlanner(host, plannerOpen, setPlannerOpen);
    // Closing the planner ends the follow, so reopening it later doesn't grab the camera. On the
    // CLOSING edge only: at load the panel is shut until a shared link opens it, and `?follow=1`
    // must survive that.
    const wasOpen = useRef(plannerOpen);
    useEffect(() => {
        if (wasOpen.current && !plannerOpen) setFollow(false);
        wasOpen.current = plannerOpen;
        // setFollow is a fresh closure each render and only writes state and the URL.
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [plannerOpen]);
    const sim = useDemoWorld(host, simulation, tickMs, planner.walk);
    // The floor in view, owned here so the transports shown are the shown floor's; seeded from
    // `?floor=` as the view seeds its own.
    const [floor, setFloor] = useState(
        () => floorIndexForKey(new URLSearchParams(location.search).get("floor")));
    // While planning, the transports the planner may take light up, as the private map's
    // "transports" layer does.
    const transports = useFloorTransports(floor, planner.open);
    // The planner's "reachable" answer: the components layer shows only these while it is set.
    const [reachable, setReachable] = useState<ReadonlySet<number> | null>(null);

    // Everything alive this tick, in the deduplicated form the view takes.
    const world: WorldEntities = useMemo(() => {
        const server = sim.server;
        if (!simulation || !server) return NOTHING_ALIVE;
        const {npcs, players} = server.entities();
        return {
            npcs: npcs.map(n => ({...n, name: names[n.id] ?? null})),
            players: players.map(p => ({...p, name: null})),
            objects: [], wallObjects: [], groundItems: [],
        };
        // sim.tick is what changes when the server steps.
    }, [sim.server, sim.tick, simulation, names]);
    // What the bot wears rides its sprite: a worn piece shows on it, as it does on any player.
    const botLook = sim.carried?.look ?? ROUTE_BOT_LOOK;
    const bot = sim.server?.bot ?? null;
    const botX = bot?.x;
    const botZ = bot?.z;
    const botFighting = bot?.opponent != null;
    const botDir = sim.server?.botDir() ?? null;
    // One synthetic observer, with no position of its own: it draws no sprite, and only carries
    // the tick that stamps the timed events. Beside it, the route bot while it walks.
    const observers: Observer[] = useMemo(() => simulation ? [{
        username: "demo", status: "online", scriptClass: null, description: null,
        serverTick: sim.tick, position: null, fatiguePercent: 0,
        sleeping: false, inCombat: false,
    }, ...(botX != null && botZ != null ? [{
        username: ROUTE_BOT, status: "online", scriptClass: null, description: null,
        serverTick: sim.tick,
        // Absolute z, as every position crossing the view's boundary is.
        position: {x: botX, z: botZ, floor: Math.floor(botZ / 944)},
        fatiguePercent: 0, sleeping: false, inCombat: botFighting, dir: botDir,
        // Each new walk leaps back to its start; its steps glide, facing and striding.
        snapSeq: sim.walkSeq,
        appearance: botLook, ringColor: ROUTE_BOT_RING,
    }] : [])] : NO_OBSERVERS,
        [sim.tick, simulation, botX, botZ, botFighting, botDir, sim.walkSeq, botLook]);
    // Three lines. Blue: while the simulation runs, the path the route bot is marching down now;
    // otherwise the planned walk. Green, while it runs: that planned walk — what the bot was
    // predicted to walk from its start tile — so its departures from it show. Dotted: the engine's
    // own route.
    const route = simulation ? sim.botPath : planner.route;
    const predicted = simulation ? planner.route : null;

    return (
        <div style={{width: "100vw", height: "100vh"}}>
            <World3DView ref={view} observers={observers} world={world} focus={{x: 122, z: 650}}
                         hideSight
                         onPickEntity={setPicked}
                         layers={{dangerZones: danger, transports: planner.open}}
                         transports={transports}
                         floorIndex={floor}
                         onFloorIndexChange={setFloor}
                         overlays={[
                             overlay("regions", regions, DEMO_REGIONS),
                             overlay("predicted", predictedOverlay, predicted),
                             overlay("route-ends", routeEnds, planner.ends),
                         ]}
                         route={route}
                         plan={planner.plan}
                         follow={follow && simulation && plannerOpen ? ROUTE_BOT : null}
                         onFollowBreak={() => setFollow(false)}
                         reachableComponents={planner.open ? reachable : null}
                         pickTool={planner.picking}
                         onTilePick={planner.session.tilePicked}
                         togglesAfterRoofs={
                             <>
                                 <label style={{marginLeft: 8, display: "flex",
                                     alignItems: "center", gap: 4}}>
                                     <input type="checkbox" checked={simulation}
                                            onChange={e => setSimulation(e.target.checked)}/>
                                     simulation
                                 </label>
                                 {simulation && (
                                     <button type="button" style={{marginLeft: 4, minWidth: 34}}
                                             title="simulation speed: the NPCs and the route bot"
                                             onClick={nextSpeed}>
                                         {speed}x
                                     </button>
                                 )}
                             </>
                         }
                         tickMs={tickMs}
                         togglesAfterTags={
                             <>
                                 <label style={{marginLeft: 8, display: "flex",
                                     alignItems: "center", gap: 4}}>
                                     <input type="checkbox" checked={planner.open}
                                            onChange={e => setPlannerOpen(e.target.checked)}/>
                                     route planner
                                 </label>
                                 <label style={{marginLeft: 8, display: "flex",
                                     alignItems: "center", gap: 4}}
                                        title="tiles an aggressive NPC makes a route pay for">
                                     <input type="checkbox" checked={danger}
                                            onChange={e => setDanger(e.target.checked)}/>
                                     danger zones
                                 </label>
                             </>
                         }/>
            {planner.open && planner.host && (
                <PlannerPanel host={planner.host} hostState={planner.hostState}
                              hostProgress={planner.progress} inputs={planner.session.inputs}
                              copySources={NO_COPY_SOURCES} itemDefs={planner.items}
                              wearableItems={planner.wearables}
                              start={planner.session.start} end={planner.session.end}
                              picking={planner.picking}
                              onClearRoute={planner.session.clear}
                              onReplan={planner.session.replan}
                              follow={follow}
                              onFollowChange={simulation ? setFollow : undefined}
                              pickTarget={planner.session.pick?.which ?? null}
                              onArmEndpoint={planner.session.armEndpoint}
                              onSetEndpoint={planner.session.setEndpoint}
                              state={planner.session.state}
                              onStateChange={planner.session.setState}
                              plan={planner.session.plan}
                              loading={planner.session.loading}
                              error={planner.session.error}
                              onHoverStep={NO_HOVER}
                              onFocusStep={t => view.current?.panTo(
                                  {x: t.x, z: t.z, floor: Math.floor(t.z / 944)})}
                              onCopyFrom={planner.session.copyFrom}
                              onClose={() => setPlannerOpen(false)}
                              onReachable={setReachable}/>
            )}
            {sim.carried && <PackWindow items={sim.carried.items} names={planner.items}/>}
            {picked && (
                <div style={{position: "absolute", bottom: 34, right: 8}}>
                    <EntityCard pick={picked} onClose={() => setPicked(null)}/>
                </div>
            )}
        </div>
    );
}

const NO_COPY_SOURCES: never[] = [];
const NO_ENDS = {start: null, end: null};
const NO_HOVER = () => {};

/**
 * The planner as the demo hosts it: nothing is downloaded until the panel first opens, and the
 * pathfinder is kept for the page's life, so closing and reopening keeps it and its warm caches.
 */
type FloorTransports = NonNullable<World3DViewProps["transports"]>;

const floorTransports = new Map<number, Promise<FloorTransports>>();

/**
 * `floor`'s transports as the bake wrote them (TransportsBaker: the view's own shape, floor-local),
 * fetched once per floor and only once `enabled` — nothing is asked for until the planner opens.
 */
function useFloorTransports(floor: number, enabled: boolean): FloorTransports | undefined {
    const [shown, setShown] = useState<{floor: number; list: FloorTransports} | null>(null);
    useEffect(() => {
        if (!enabled) return;
        let alive = true;
        let p = floorTransports.get(floor);
        if (!p) {
            p = versioned(`/api/map/floor/${floor}.transports.json`)
                .then(url => fetch(url))
                .then(r => (r.ok ? r.json() as Promise<FloorTransports> : []))
                .catch(e => {
                    console.warn(`[transports] floor ${floor}:`, e);
                    return [];
                });
            floorTransports.set(floor, p);
        }
        p.then(list => alive && setShown({floor, list}));
        return () => {
            alive = false;
        };
    }, [floor, enabled]);
    return enabled && shown?.floor === floor ? shown.list : undefined;
}

/**
 * The route bot's look: a fresh account's, as SkipTutorialV2 sets it —
 * {@code AppearanceUpdatePacket(1, HEAD_SPRITES[3], BODY_SPRITES[0], 7, 11, 11, 0)}. The server
 * wears head type + 1 and body type + 1 with the default legs (3), so the sprites are 7, 2, 3;
 * then hair 7, top 11, trousers 11, skin 0.
 */
const ROUTE_BOT_LOOK = formatAppearance({
    sprites: [7, 2, 3, 0, 0, 0, 0, 0, 0, 0, 0, 0], hair: 7, top: 11, bottom: 11, skin: 0,
});
/** Its ring: the planner's green, apart from the bots' blue. */
const ROUTE_BOT_RING = 0x58ff8a;


/** The pathfinder's worker, started the first time it is `wanted` and kept for the page's life. */
function useNavHost(wanted: boolean): WasmPlannerHost | null {
    const [host, setHost] = useState<WasmPlannerHost | null>(null);
    useEffect(() => {
        if (wanted && !host) setHost(wasmPlannerHost());
    }, [wanted, host]);
    useEffect(() => (host ? () => host.dispose() : undefined), [host]);
    return host;
}

/** A plan to walk: the request it answered, and a number that changes with every new answer. */
interface DemoWalk {
    req: PlanRequest;
    seq: number;
}

function useDemoPlanner(host: WasmPlannerHost | null, open: boolean,
                        setOpen: (open: boolean) => void) {
    const [opened, setOpened] = useState(false);
    const [items, setItems] = useState<ItemNames | null>(null);
    const [wearables, setWearables] = useState<ReadonlySet<number> | null>(null);
    const [built, setBuilt] = useState(false);
    const [failed, setFailed] = useState<string | null>(null);
    const [progress, setProgress] = useState<string | null>(null);
    useEffect(() => {
        if (open) setOpened(true);
    }, [open]);
    // Nothing is built until the panel first opens; the pathfinder is kept for the page's life, so
    // closing and reopening keeps it and its warm caches.
    useEffect(() => {
        if (!host || !opened) return;
        const unfollow = host.onProgress(setProgress);
        host.pathfinder().then(() => setBuilt(true), e => setFailed(String(e?.message ?? e)));
        host.items().then(setItems, () => setItems({}));
        host.wearableItems().then(ids => setWearables(new Set(ids)), () => setWearables(new Set()));
        return unfollow;
    }, [host, opened]);
    // Each answer remembers the request it answered, so the route bot can walk it.
    const asked = useRef(new WeakMap<PlanResponse, PlanRequest>());
    const sessionHost = useMemo<PlannerHost | null>(() => host && {
        inputs: () => host.inputs(),
        account: (req) => host.account(req),
        reachable: (req) => host.reachable(req),
        plan: (req) => host.plan(req).then(r => {
            asked.current.set(r, req);
            return r;
        }),
    }, [host]);
    // Handed over only once the panel has opened: asking the catalogue is what builds the pathfinder.
    const session = usePlannerSession(opened ? sessionHost : null);
    // `?plan=` opens the panel and fills it; while open, every change rewrites it — a shareable link.
    usePlannerUrlSync({
        open, setOpen, inputs: session.inputs, state: session.state, setState: session.setState,
        start: session.start, end: session.end, setEndpoint: session.setEndpoint,
    });
    const seq = useRef(0);
    const walk = useMemo<DemoWalk | null>(() => {
        const req = open && session.plan?.found ? asked.current.get(session.plan) : undefined;
        return req ? {req, seq: ++seq.current} : null;
    }, [open, session.plan]);
    const ends = useMemo(() => open
        ? {start: session.start, end: session.end} : NO_ENDS, [open, session.start, session.end]);
    const route = useMemo(() => open && session.plan?.found
        ? session.plan.steps.map(s => ({x: s.x, z: s.z, hop: s.type === "hop"}))
        : null, [open, session.plan]);
    // The engine's own route beside the walk: dotted, from the same answer.
    const plan = useMemo(() => open && session.plan?.found
        ? enginePlanPoints(session.start, session.plan.plan)
        : null, [open, session.plan, session.start]);
    const hostState: PlannerHostState = failed ? {failed} : built ? "ready" : "loading";
    return {
        open, host: opened ? host : null, items, wearables, session, route, plan, ends, hostState,
        progress,
        walk, picking: open && session.pick != null,
    };
}

/** Players wandering Lumbridge, as `layers|colours` exactly as the wire carries them. */
const DEMO_PLAYERS = [
    {x: 122, z: 648, appearance: "1,34,42,103,53,75,0,0,47,12,0,63|0,8,14,0"}, // full rune kit
    {x: 135, z: 655, appearance: "1,2,3|3,0,11,2"},                             // plain male
    {x: 115, z: 660, appearance: "6,2,3|6,9,4,1"},                              // plain male, head2
    {x: 128, z: 640, appearance: "4,5,3|1,12,2,3"},                             // plain female
];

/** Most ticks the server catches up in one frame; a tab left in the background skips ahead. */
const MAX_CATCH_UP = 10;

/**
 * The demo's world, played as a server: built from the pathfinder's world the first time the
 * simulation runs, stepped once a tick while it runs. With a plan to `walk`, a route bot is put on
 * its start and the worker walks it: each tick it is sent what the bot sees, and what it answers is
 * the bot's packet for the next tick. A bot whose answer is late is simply late, as a live one is —
 * the server walks what it sent last.
 */
function useDemoWorld(host: WasmPlannerHost | null, simulation: boolean, tickMs: number,
                      walk: DemoWalk | null) {
    const [server, setServer] = useState<DemoServer | null>(null);
    const [tick, setTick] = useState(0);
    const [botPath, setBotPath] = useState<{x: number; z: number; hop: boolean}[] | null>(null);
    // What the bot holds and banks, and the appearance its worn pieces give.
    const [carried, setCarried] = useState<{items: PackItem[]; look: string} | null>(null);
    const [walkSeq, setWalkSeq] = useState<number | undefined>(undefined);
    useEffect(() => {
        if (!host || !simulation || server) return;
        let alive = true;
        host.serverWorld().then(({world, steps}) => {
            if (alive) setServer(new DemoServer(world, steps, DEMO_PLAYERS));
        }, e => console.error("[simulation] the world did not load:", e));
        return () => {
            alive = false;
        };
    }, [host, simulation, server]);

    // The server's transport table, asked once: it comes with the pathfinder.
    const transportsRef = useRef<Promise<ServerTransport[]> | null>(null);
    // The walk the bot is on: which one, how far it sees, and whether it still asks.
    const walking = useRef<{seq: number; radius: number; busy: boolean; done: boolean;
        waited: boolean} | null>(null);
    useEffect(() => {
        if (!server || !host) return;
        walking.current = null;
        server.removeBot();
        setBotPath(null);
        setCarried(null);
        if (!simulation || !walk) return;
        const {req, seq} = walk;
        let alive = true;
        Promise.all([host.walkStart(req), transportsRef.current ??= host.serverTransports()]).then(([info, list]) => {
            if (!alive) return; // a newer walk, or none, since
            server.setTransports(list);
            server.spawnBot(req.from.x, req.from.z, info.combatLevel);
            walking.current = {seq, radius: info.viewRadius, busy: false, done: false,
                waited: false};
            setWalkSeq(seq);
        }, e => console.warn("[route bot] the walk did not start:", e));
        return () => {
            alive = false;
            walking.current = null;
            server.removeBot();
            setBotPath(null);
            setCarried(null);
        };
    }, [server, host, simulation, walk]);

    // The clock is anchored where it last (re)started — (time, tick) — so a new speed carries on
    // from the tick already reached.
    useEffect(() => {
        if (!server || !host || !simulation) return;
        let anchor: {at: number; tick: number} | null = null;
        let raf = 0;
        const loop = (t: number) => {
            if (!anchor) anchor = {at: t, tick: server.tick};
            let due = anchor.tick + Math.floor((t - anchor.at) / tickMs) - server.tick;
            if (due > MAX_CATCH_UP) {
                anchor = {at: t, tick: server.tick + 1};
                due = 1;
            }
            for (; due > 0; due--) {
                // Lockstep: the server waits for the bot. A tick played before the bot has answered
                // the last one applies a move made from where it stood ticks ago — on a slow machine
                // or at a high speed it paced back and forth instead of walking. So a tick comes due
                // no sooner than the answer, and the clock restarts from here: the speed is a cap.
                const w = walking.current;
                if (w?.busy) {
                    if (!w.waited) {
                        w.waited = true;
                        console.info("[route bot] the simulation is waiting on the bot's answers:"
                            + " it runs slower than the chosen speed");
                    }
                    // Due again the moment the answer is in — no debt piles up meanwhile.
                    anchor = {at: t - tickMs, tick: server.tick};
                    break;
                }
                server.step();
                ask();
            }
            setTick(server.tick);
            raf = requestAnimationFrame(loop);
        };
        const ask = () => {
            const w = walking.current;
            if (!w || w.busy || w.done) return;
            const seen = server.view(w.radius);
            if (!seen) return;
            w.busy = true;
            host.walkTick(seen).then(move => {
                if (walking.current !== w) return;
                w.busy = false;
                server.send(move.packets);
                if (move.move === "arrived" || move.move === "stuck") {
                    w.done = true;
                    if (move.move === "stuck") console.warn(`[route bot] stuck: ${move.why}`);
                } else if (move.unsent) {
                    // A crossing this page cannot play (a scripted one): the walk ends at it.
                    w.done = true;
                    console.warn(`[route bot] cannot take ${move.unsent}`);
                }
                const p = move.path;
                setBotPath(p ? Array.from({length: p.length / 2},
                    (_, i) => ({x: p[2 * i], z: p[2 * i + 1], hop: false})) : null);
                setCarried(packOf(move.pack, move.bank, move.worn));
            }, e => {
                w.busy = false;
                w.done = true;
                console.warn("[route bot] the walk failed:", e);
            });
        };
        raf = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(raf);
    }, [server, host, simulation, tickMs]);
    return {server, tick, botPath, walkSeq, carried};
}

/**
 * One window's worth of what the bot owns: every item it carries or banks, and the appearance its
 * worn pieces give — the route bot's own look with each worn piece's sprite in its wield position,
 * which is what the server puts in {@code wornItems} (Player#updateWornItems).
 */
function packOf(pack: [number, number, number][] = [], bank: [number, number][] = [],
                worn: [number, number][] = []): {items: PackItem[]; look: string} {
    const items = new Map<number, PackItem>();
    for (const [id, count, wearing] of pack) {
        items.set(id, {id, held: count, banked: 0, worn: wearing !== 0});
    }
    for (const [id, count] of bank) {
        const at = items.get(id);
        if (at) at.banked = count;
        else items.set(id, {id, held: 0, banked: count, worn: false});
    }
    const look = parseAppearance(ROUTE_BOT_LOOK);
    const sprites = [...look.sprites];
    for (const [slot, sprite] of worn) {
        if (slot >= 0 && slot < sprites.length) sprites[slot] = sprite;
    }
    return {items: [...items.values()], look: formatAppearance({...look, sprites})};
}

function App() {
    const [names, setNames] = useState<Record<number, string> | null>(null);
    const [err, setErr] = useState<string | null>(null);
    useEffect(() => {
        // The simulation carries def ids only; names come from the spawn table the view loads anyway.
        fetchNpcSpawns()
            .then(spawns => {
                const out: Record<number, string> = {};
                for (const s of spawns) if (s.name) out[s.id] = s.name;
                setNames(out);
            })
            .catch(e => setErr(String(e)));
    }, []);
    if (err) {
        return <div style={{width: "100vw", height: "100vh"}}>
            <World3DView observers={NO_OBSERVERS} focus={{x: 122, z: 650}}
                         onPickEntity={() => {}}/>
        </div>;
    }
    if (!names) return <div style={{padding: 16}}>Loading world…</div>;
    return <Demo names={names}/>;
}

createRoot(document.getElementById("root")!).render(<App/>);
