import * as THREE from "three";
import {freezeTransform} from "./staticTransform";
import {uploadQuads} from "./bufferUpload";
import {classOfSlot, cropIndex, loadPlayerLayerAtlas, palClamp,
    type PlayerLayerAtlas} from "./playerLayerAtlas";

/**
 * Equipped player/bot sprites.
 *
 * <p>One quad per WORN LAYER, all players in one batch, all sampling the single
 * per-layer atlas; the recolour happens in the fragment shader off the mask tag
 * the atlas carries in its alpha byte. That is what the reference clients do —
 * the stock Java client recolours per pixel inside its blit kernel, rsc-c's GL
 * renderer in one multiply-add (cache/flat.fs) — and neither builds a
 * per-appearance strip.
 *
 * <p>This replaces a CPU compositor that built all 30 frames (10 facings × 3
 * walk steps) × 12 layers for every {@code layers|colours} token before the
 * player could be drawn once, cached the result as a texture per token, and
 * therefore also needed a token cache, a TTL, an eviction pass and a
 * new-strips-per-frame throttle. In a bot swarm the token space is nearly as
 * large as the population — 132 live strips, ~3.5 brand-new tokens a second
 * while panning — so the per-token amortisation the design assumed never
 * happened: each new appearance cost a ~45 ms block in the middle of a frame,
 * and the 132 strips were 264 of the view's ~400 draw calls. None of that
 * exists here: the cost of an appearance nobody has worn before is the same as
 * one everybody wears, and every player on screen is one draw.
 *
 * <p>Facing/walk/mirror math is unchanged and still matches the NPC layer.
 */

export interface PlayerSpriteState {
    key: string;
    appearance: string;
    x: number;
    z: number;
    moving: boolean;
    dx: number;
    dz: number;
    /** Server sprite direction: 0-7 facing, 8/9 = combat stance A/B. */
    dir?: number | null;
    /** Not live — draw into the translucent ghost batch instead of the solid one. */
    offline?: boolean;
}

const WALK_CYCLE = [0, 1, 2, 1];
// Combat swing cycles (mudclient animFrameToSprite_CombatA/B); see the NPC
// layer for the client provenance. Players hardcode combat divisors 5 (A) /
// 6 (B) and walk divisor 6.
const COMBAT_CYCLE_A = [0, 1, 2, 1, 0, 0, 0, 0];
const COMBAT_CYCLE_B = [0, 0, 0, 0, 0, 1, 2, 1];
const CLIENT_FRAME_MS = 20; // the client's 50fps logic tick

// Per-frame scratch — allocation-free corner math, as in the NPC layer.
const T_BL = new THREE.Vector3();
const T_BR = new THREE.Vector3();
const T_TR = new THREE.Vector3();
const T_TL = new THREE.Vector3();
const T_WP = new THREE.Vector3();

/** Worn layers per player. */
const SLOTS = 12;
/** Players the batch can draw. The server's max_players is 2000; beyond this
 *  extras are skipped, which degrades a crowd rather than breaking it. */
const MAX_PLAYERS = 2048;
const MAX_QUADS = MAX_PLAYERS * SLOTS;
/** Offline observers drawn as ghosts. Far smaller than the live batch: these are one host's own
 *  parked bots on the current plane, not a server's worth of players. */
const MAX_PHANTOM_PLAYERS = 512;
const MAX_PHANTOM_QUADS = MAX_PHANTOM_PLAYERS * SLOTS;

/**
 * Six bits per palette index, packed into one float attribute. Four separate
 * floats per vertex made `pal` the largest thing the batch uploaded — bigger
 * than the positions — for four small integers that are constant across a
 * player's twelve quads. 6 bits is ample: the palettes are 10 hair, 15
 * clothing, 5 skin, and the packed value stays exact in float32 well past 64
 * entries each.
 */
const PAL_SHIFT = 64;
const PAL_MAX = PAL_SHIFT;

/** Parsed appearances kept around; comfortably above any crowd's worth of
 *  simultaneous looks. */
const LOOK_CACHE_CAP = 4096;

/** Parsed appearance token: 12 layer anim ids + the packed palette indices. */
interface Look {
    layers: Int32Array;
    pal: number;
}

/**
 * The recolour, straight out of the engine kernel
 * ({@code plot_trans_scale_with_2_masks}).
 *
 * <p>`t.r` IS the shade byte normalised, so the kernel's
 * {@code colour * shade / 255} is a plain multiply here. Skin is the one mask
 * that is not: its red channel is pinned (`* 255 >> 8`) while green and blue
 * ride the ramp.
 *
 * <p>Written out with no colour-space conversion, exactly like the raw world
 * materials — the atlas is NoColorSpace, so a pixel reaches the screen as the
 * byte the bake produced. (A built-in material would decode the texture as sRGB
 * and re-encode on output; those cancel, which is why the composited-canvas
 * path had to mark its texture sRGB. Here neither happens.)
 */
function fragmentShader(nHair: number, nCloth: number, nSkin: number) {
    return /* glsl */ `
precision highp float;
uniform sampler2D map;
uniform vec3 hairPal[${nHair}];
uniform vec3 clothPal[${nCloth}];
uniform vec3 skinPal[${nSkin}];
uniform float uOpacity;
/** Flat-colour override for the highlight halo; alpha 0 = shade normally. */
uniform vec4 uFlat;
in vec2 vUv;
// flat: the packed indices are identical at all four corners and are used as
// array subscripts, so interpolating them risks 3.0 arriving as 2.9999996.
flat in float vPal;
out vec4 outColor;
void main() {
    vec4 t = texture(map, vUv);
    // The alpha byte tags the mask; 0 is empty, and nothing else is coverage.
    float tag = floor(t.a * 255.0 + 0.5);
    if (tag < 0.5) discard;
    if (uFlat.a > 0.5) { outColor = vec4(uFlat.rgb, uOpacity); return; }
    // hair | top<<6 | bottom<<12 | skin<<18, see PAL_SHIFT.
    vec3 rgb;
    if (tag > 253.5) {
        // 0xFF already final, 0xFE hair.
        rgb = tag > 254.5 ? t.rgb : hairPal[int(mod(vPal, 64.0))] * t.r;
    } else if (tag > 251.5) {
        // 0xFD top, 0xFC bottom — both come out of the clothing palette.
        float c = tag > 252.5 ? floor(vPal / 64.0) : floor(vPal / 4096.0);
        rgb = clothPal[int(mod(c, 64.0))] * t.r;
    } else if (tag > 250.5) {
        vec3 sk = skinPal[int(mod(floor(vPal / 262144.0), 64.0))];
        rgb = vec3(sk.r * (255.0 / 256.0), sk.g * t.r, sk.b * t.r);
    } else {
        rgb = t.rgb; // unrecognised tag: the kernel takes the pixel as-is
    }
    outColor = vec4(rgb, uOpacity);
}`;
}

const VERTEX_SHADER = /* glsl */ `
in vec3 position;
in vec2 uv;
/** Packed palette indices: hair | top<<6 | bottom<<12 | skin<<18. */
in float pal;
uniform mat4 modelViewMatrix;
uniform mat4 projectionMatrix;
out vec2 vUv;
flat out float vPal;
void main() {
    vUv = uv;
    vPal = pal;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;

function paletteVectors(table: number[]): THREE.Vector3[] {
    return table.map(c => new THREE.Vector3(
        ((c >> 16) & 255) / 255, ((c >> 8) & 255) / 255, (c & 255) / 255));
}

export class PlayerSpriteLayer {
    private readonly scene: THREE.Scene;
    private atlas: PlayerLayerAtlas | null = null;
    private readonly geo: THREE.BufferGeometry;
    private solid: THREE.Mesh | null = null;
    private ghost: THREE.Mesh | null = null;
    /** Offline observers: the same layered quads at a fraction of the alpha, plus their own
     *  X-ray pass — a parked bot behind a wall would otherwise show only its nameplate. */
    private readonly phantomGeo: THREE.BufferGeometry;
    private phantom: THREE.Mesh | null = null;
    private phantomXray: THREE.Mesh | null = null;
    /** Highlight halo: the same layer quads, scaled about their centre. */
    private readonly glowGeo: THREE.BufferGeometry;
    private glow: THREE.Mesh | null = null;
    /** Sprite drawn with an additive glow halo (hover/selection feedback). */
    highlightKey: string | null = null;
    private readonly lastDir = new Map<string, number>();
    /** Stock stepFrame: fractional client frames walked, per entity. Advances
     *  only while moving (per axis — diagonals count double), never resets, so
     *  a stopped character freezes mid-stride exactly like the game. */
    private readonly stepAcc = new Map<string, number>();
    private lastFrameNow = -1;
    /** Parsed tokens. Parsing is cheap but it is per player per frame, and the
     *  same handful of appearances repeat across a crowd. Bounded because
     *  tokens churn for the life of the page — every re-equip mints a new one —
     *  and a re-parse costs a string split. */
    private readonly looks = new Map<string, Look>();

    constructor(scene: THREE.Scene) {
        this.scene = scene;
        this.geo = new THREE.BufferGeometry();
        this.phantomGeo = new THREE.BufferGeometry();
        this.glowGeo = new THREE.BufferGeometry();
        allocQuads(this.geo, MAX_QUADS);
        allocQuads(this.phantomGeo, MAX_PHANTOM_QUADS);
        allocQuads(this.glowGeo, SLOTS);
        loadPlayerLayerAtlas()
            .then(a => this.build(a))
            .catch(e => console.error("[players] layer atlas", e));
    }

    private build(atlas: PlayerLayerAtlas) {
        this.atlas = atlas;
        for (const [name, table] of Object.entries(atlas.palettes)) {
            if (table.length > PAL_MAX) {
                console.error(`[players] ${name} palette has ${table.length} `
                    + `entries; the packed attribute holds ${PAL_MAX}`);
            }
        }
        const shared = {
            map: {value: atlas.tex},
            hairPal: {value: paletteVectors(atlas.palettes.hair)},
            clothPal: {value: paletteVectors(atlas.palettes.clothing)},
            skinPal: {value: paletteVectors(atlas.palettes.skin)},
        };
        const frag = fragmentShader(atlas.palettes.hair.length,
            atlas.palettes.clothing.length, atlas.palettes.skin.length);
        const make = (extra: THREE.MaterialParameters,
                      opacity: number, flat: THREE.Vector4) =>
            new THREE.RawShaderMaterial({
                glslVersion: THREE.GLSL3,
                vertexShader: VERTEX_SHADER,
                fragmentShader: frag,
                uniforms: {...shared, uOpacity: {value: opacity},
                    uFlat: {value: flat}},
                side: THREE.DoubleSide,
                ...extra,
            });
        const NO_FLAT = new THREE.Vector4(0, 0, 0, 0);
        // `transparent` even though every surviving fragment has alpha 1 — this
        // is an ORDERING flag, not a blending one. three draws the whole opaque
        // pass before any transparent object, and renderOrder only sorts WITHIN
        // a pass, so an opaque sprite is always drawn before the glow below it
        // no matter what renderOrder says: the halo then paints additively over
        // the whole sprite instead of ringing it. (That is what the npc layer,
        // whose solid has always been transparent, gets right.) Blending is
        // still a no-op at alpha 1, and depthWrite keeps resolving stacks of
        // co-located sprites by depth exactly as before.
        //
        // forceSinglePass because the batch is DoubleSide: without it three
        // splits every transparent DoubleSide draw into a back pass and a front
        // pass, flipping material.side and setting needsUpdate between them —
        // two program rebuilds per frame for pixels that cannot overlap.
        this.solid = new THREE.Mesh(this.geo, make(
            {transparent: true, forceSinglePass: true}, 1, NO_FLAT));
        this.solid.renderOrder = 12;
        // X-ray pass: GreaterDepth paints only where the sprite is OCCLUDED.
        // depthWrite stays on so a stack of co-located ghosts doesn't composite
        // its alpha into an opaque blob — the first writes depth, the rest fail
        // the strict test.
        this.ghost = new THREE.Mesh(this.geo, make(
            {transparent: true, depthFunc: THREE.GreaterDepth, depthWrite: true,
                forceSinglePass: true}, 0.3, NO_FLAT));
        this.ghost.renderOrder = 13;
        this.glow = new THREE.Mesh(this.glowGeo, make(
            {transparent: true, blending: THREE.AdditiveBlending,
                depthWrite: false, forceSinglePass: true},
            1, new THREE.Vector4(1, 0.894, 0.361, 1)));
        this.glow.renderOrder = 11;
        // Offline observers: the npc layer's phantom treatment, one batch behind. depthWrite is
        // OFF here (unlike the X-ray pass above) because a ghost must not occlude the live swarm
        // standing behind it; the cost is that a character's twelve layers composite where they
        // genuinely overlap — a weapon or cape reads slightly denser than the body, which on a
        // deliberately faded sprite is not worth a second render target to avoid.
        this.phantom = new THREE.Mesh(this.phantomGeo, make(
            {transparent: true, depthWrite: false, forceSinglePass: true}, 0.4, NO_FLAT));
        this.phantom.renderOrder = 12;
        this.phantomXray = new THREE.Mesh(this.phantomGeo, make(
            {transparent: true, depthFunc: THREE.GreaterDepth, depthWrite: false,
                forceSinglePass: true}, 0.12, NO_FLAT));
        this.phantomXray.renderOrder = 13;
        // Named so the offline batch is findable in the scene graph (three devtools / a headless
        // check reads its drawRange to confirm ghosts are actually being drawn).
        this.phantom.name = "playerGhosts";
        this.phantomXray.name = "playerGhostsXray";
        for (const m of [this.solid, this.ghost, this.glow,
                         this.phantom, this.phantomXray]) {
            m.frustumCulled = false;
            m.userData.noPick = true; // exclude from the GPU depth pick
            m.visible = false;        // until frame() writes quads
            this.scene.add(freezeTransform(m));
        }
    }

    private look(token: string): Look {
        let l = this.looks.get(token);
        if (l) return l;
        const atlas = this.atlas!;
        const halves = token.split("|");
        const layerStr = (halves[0] ?? "").split(",");
        const layers = new Int32Array(SLOTS);
        for (let i = 0; i < SLOTS; i++) {
            layers[i] = i < layerStr.length ? (parseInt(layerStr[i], 10) || 0) : 0;
        }
        const cs = (halves[1] ?? "").split(",").map(n => parseInt(n, 10) || 0);
        l = {
            layers,
            pal: palClamp(atlas.palettes.hair, cs[0] ?? 0)
                + palClamp(atlas.palettes.clothing, cs[1] ?? 0) * PAL_SHIFT
                + palClamp(atlas.palettes.clothing, cs[2] ?? 0) * PAL_SHIFT ** 2
                + palClamp(atlas.palettes.skin, cs[3] ?? 0) * PAL_SHIFT ** 3,
        };
        this.looks.set(token, l);
        while (this.looks.size > LOOK_CACHE_CAP) {
            const oldest = this.looks.keys().next();  // Map iterates insertion order
            if (oldest.done) break;
            this.looks.delete(oldest.value);
        }
        return l;
    }

    frame(now: number, players: PlayerSpriteState[],
          toWorld: (x: number, z: number) => THREE.Vector3,
          camRight: THREE.Vector3, camUp: THREE.Vector3, camYaw: number,
          camToward: THREE.Vector3, lift: number) {
        const atlas = this.atlas;
        if (!atlas || !this.solid || !this.ghost || !this.glow
            || !this.phantom || !this.phantomXray) return;
        const camRot = Math.round((camYaw / (2 * Math.PI)) * 256) & 255;
        const dtFrames = this.lastFrameNow < 0 ? 0
            : (now - this.lastFrameNow) / CLIENT_FRAME_MS;
        this.lastFrameNow = now;
        const posA = this.geo.getAttribute("position").array as Float32Array;
        const uvA = this.geo.getAttribute("uv").array as Float32Array;
        const palA = this.geo.getAttribute("pal").array as Float32Array;
        const pPosA = this.phantomGeo.getAttribute("position").array as Float32Array;
        const pUvA = this.phantomGeo.getAttribute("uv").array as Float32Array;
        const pPalA = this.phantomGeo.getAttribute("pal").array as Float32Array;
        const crops = atlas.crops;
        const invScale = 1 / atlas.scale;
        const anchorX = atlas.originX + (atlas.width1 >> 1);
        const anchorY = atlas.originY + atlas.height;
        const dbg: Record<string, {order: number; frame: number;
            layers: number; appearance: string}> = {};
        let q = 0;
        let pq = 0;
        let glowQuads = 0;
        for (const p of players) {
            if (!p.appearance) continue;
            // Offline observers write into the phantom batch; everything below is identical, so
            // one loop serves both and a ghost animates (facing, frozen stride) exactly as it did
            // the moment it went offline.
            const ghosted = p.offline === true;
            const outPos = ghosted ? pPosA : posA;
            const outUv = ghosted ? pUvA : uvA;
            const outPal = ghosted ? pPalA : palA;
            if (ghosted ? pq + SLOTS > MAX_PHANTOM_QUADS : q + SLOTS > MAX_QUADS) continue;
            const look = this.look(p.appearance);
            // Never walked and no server facing: the spawn default, which is
            // Mob.mobSprite = 0 (north) — same rule as the npc layer.
            let dir = this.lastDir.get(p.key) ?? 0;
            if (p.moving && (p.dx !== 0 || p.dz !== 0)) {
                const ang = Math.atan2(p.dx, -p.dz);
                dir = Math.round(((ang + 2 * Math.PI) % (2 * Math.PI)) / (Math.PI / 4)) & 7;
                this.lastDir.set(p.key, dir);
            } else if (p.dir != null && p.dir >= 0 && p.dir <= 7) {
                // Stopped: face the server-dictated standing direction, as the
                // stock client does (mudclient.java:11738, reaching the last
                // waypoint: direction = lookup(animationNext)).
                dir = p.dir;
                this.lastDir.set(p.key, dir);
            }
            // Stock stepFrame: advance while moving, one count per moving axis
            // per 20ms client frame; freeze (don't reset) when still.
            if (p.moving && dtFrames > 0) {
                const axes = (p.dx !== 0 ? 1 : 0) + (p.dz !== 0 ? 1 : 0);
                this.stepAcc.set(p.key,
                    (this.stepAcc.get(p.key) ?? 0) + axes * dtFrames);
            }
            const stepFrame = Math.floor(this.stepAcc.get(p.key) ?? 0);
            let order = (4 - dir + ((camRot + 16) >> 5)) & 7;
            // Walk frame = WALK[stepFrame / 6 % 4] (drawPlayer).
            let walk = WALK_CYCLE[Math.floor(stepFrame / 6) % 4];
            if (p.dir === 8 || p.dir === 9) {
                // Stock combat render: both fighters overlap at the same spot
                // (the ±30 is pick-only) — see the NPC layer. A faces right via
                // the flipped frame set, B left.
                order = p.dir === 8 ? 9 : 8;
                walk = p.dir === 8
                    ? COMBAT_CYCLE_A[Math.floor(now / 100) % 8]
                    : COMBAT_CYCLE_B[Math.floor(now / 120) % 8];
            }
            const wp = T_WP.copy(toWorld(p.x, p.z)).addScaledVector(camToward, lift);
            const drawOrder = atlas.layerOrder[order <= 7 ? order : 2];
            const glowing = p.key === this.highlightKey;
            const first = ghosted ? pq : q;
            for (let d = 0; d < drawOrder.length; d++) {
                const slot = drawOrder[d];
                const animId = look.layers[slot] - 1;
                if (animId < 0 || animId > atlas.maxAnim) continue;
                const at = cropIndex(animId, classOfSlot(slot), order, walk);
                const ax = crops[at];
                if (ax < 0) continue;
                const ay = crops[at + 1], w = crops[at + 2], h = crops[at + 3];
                const dx = crops[at + 4], dy = crops[at + 5];
                // The layer's own anchor in the composition surface: the strip
                // formula with the LAYER's offset instead of the assembled
                // frame's bounding box.
                const lax = anchorX - dx, lay = anchorY - dy;
                const w0 = ghosted ? pq : q;
                writeQuad(outPos, outUv, w0, wp, camRight, camUp,
                    -lax * invScale, (w - lax) * invScale,
                    lay * invScale, -(h - lay) * invScale,
                    ax / atlas.atlasW, (ax + w) / atlas.atlasW,
                    ay / atlas.atlasH, (ay + h) / atlas.atlasH);
                outPal[w0 * 4] = look.pal;
                outPal[w0 * 4 + 1] = look.pal;
                outPal[w0 * 4 + 2] = look.pal;
                outPal[w0 * 4 + 3] = look.pal;
                if (ghosted) pq++; else q++;
            }
            const last = ghosted ? pq : q;
            dbg[p.key] = {order, frame: walk, layers: last - first,
                appearance: p.appearance};
            if (glowing && last > first) {
                glowQuads = inflateInto(this.glowGeo, outPos, outUv, first, last, 1.12);
            }
        }
        uploadQuads(this.geo, q, "position", "uv", "pal");
        uploadQuads(this.phantomGeo, pq, "position", "uv", "pal");
        this.geo.setDrawRange(0, q * 6);
        this.phantomGeo.setDrawRange(0, pq * 6);
        this.solid.visible = q > 0;
        this.ghost.visible = q > 0;
        this.phantom.visible = pq > 0;
        this.phantomXray.visible = pq > 0;
        this.glowGeo.setDrawRange(0, glowQuads * 6);
        this.glow.visible = glowQuads > 0;
        (window as any).__playerSprites = dbg;
    }

    dispose() {
        for (const m of [this.solid, this.ghost, this.glow,
                         this.phantom, this.phantomXray]) {
            if (!m) continue;
            this.scene.remove(m);
            (m.material as THREE.Material).dispose();
        }
        this.phantomGeo.dispose();
        this.geo.dispose();
        this.glowGeo.dispose();
        // The atlas texture is NOT disposed: loadPlayerLayerAtlas caches it for
        // the life of the page, so a remounted view re-uses it rather than
        // re-fetching and re-decoding a 2048×3239 PNG.
    }
}

/** Allocate a quad batch: 4 vertices and 6 indices each. */
function allocQuads(geo: THREE.BufferGeometry, quads: number) {
    geo.setAttribute("position",
        new THREE.BufferAttribute(new Float32Array(quads * 4 * 3), 3));
    geo.setAttribute("uv",
        new THREE.BufferAttribute(new Float32Array(quads * 4 * 2), 2));
    geo.setAttribute("pal",
        new THREE.BufferAttribute(new Float32Array(quads * 4), 1));
    // Uint32: twelve quads per player overruns the 65535-vertex Uint16 ceiling
    // at ~1365 players, well inside a full server.
    const idx = new Uint32Array(quads * 6);
    for (let i = 0; i < quads; i++) {
        idx.set([i * 4, i * 4 + 1, i * 4 + 2, i * 4, i * 4 + 2, i * 4 + 3], i * 6);
    }
    geo.setIndex(new THREE.BufferAttribute(idx, 1));
    geo.setDrawRange(0, 0);
}

/** One camera-facing quad, written straight into the batch arrays. */
function writeQuad(posA: Float32Array, uvA: Float32Array, q: number,
                   wp: THREE.Vector3, camRight: THREE.Vector3, camUp: THREE.Vector3,
                   left: number, right: number, top: number, bottom: number,
                   u0: number, u1: number, v0: number, v1: number) {
    const bl = T_BL.copy(wp).addScaledVector(camRight, left).addScaledVector(camUp, bottom);
    const br = T_BR.copy(wp).addScaledVector(camRight, right).addScaledVector(camUp, bottom);
    const tr = T_TR.copy(wp).addScaledVector(camRight, right).addScaledVector(camUp, top);
    const tl = T_TL.copy(wp).addScaledVector(camRight, left).addScaledVector(camUp, top);
    const p = q * 12;
    posA[p] = bl.x; posA[p + 1] = bl.y; posA[p + 2] = bl.z;
    posA[p + 3] = br.x; posA[p + 4] = br.y; posA[p + 5] = br.z;
    posA[p + 6] = tr.x; posA[p + 7] = tr.y; posA[p + 8] = tr.z;
    posA[p + 9] = tl.x; posA[p + 10] = tl.y; posA[p + 11] = tl.z;
    const u = q * 8;
    uvA[u] = u0; uvA[u + 1] = v1;
    uvA[u + 2] = u1; uvA[u + 3] = v1;
    uvA[u + 4] = u1; uvA[u + 5] = v0;
    uvA[u + 6] = u0; uvA[u + 7] = v0;
}

/**
 * Copy quads `[from, to)` into the glow batch, each scaled about the WHOLE
 * sprite's centre so the halo is one outline rather than twelve.
 */
function inflateInto(glowGeo: THREE.BufferGeometry, posA: Float32Array,
                     uvA: Float32Array, from: number, to: number,
                     scale: number): number {
    const gpos = glowGeo.getAttribute("position") as THREE.BufferAttribute;
    const guv = glowGeo.getAttribute("uv") as THREE.BufferAttribute;
    const gp = gpos.array as Float32Array;
    const gu = guv.array as Float32Array;
    let cx = 0, cy = 0, cz = 0, n = 0;
    for (let i = from * 12; i < to * 12; i += 3) {
        cx += posA[i]; cy += posA[i + 1]; cz += posA[i + 2]; n++;
    }
    if (n === 0) return 0;
    cx /= n; cy /= n; cz /= n;
    let g = 0;
    for (let q = from; q < to && g < SLOTS; q++, g++) {
        const s = q * 12, d = g * 12;
        for (let v = 0; v < 4; v++) {
            gp[d + v * 3] = cx + (posA[s + v * 3] - cx) * scale;
            gp[d + v * 3 + 1] = cy + (posA[s + v * 3 + 1] - cy) * scale;
            gp[d + v * 3 + 2] = cz + (posA[s + v * 3 + 2] - cz) * scale;
        }
        gu.set(uvA.subarray(q * 8, q * 8 + 8), g * 8);
    }
    uploadQuads(glowGeo, g, "position", "uv");
    return g;
}
