import {useEffect, useState} from "react";
import {getItemAtlas, ItemIcon, type ItemAtlasIndex} from "../ItemIcon";
import "./pack.css";

/**
 * What the route bot carries and what its bank holds, drawn the way the game's bank window draws
 * the pair: one slot per item, the number in the BANK over it in green and the number HELD under it
 * in blue, and a worn piece backed in red.
 *
 * <p>The colours and the layout are the stock client's, in this demo's chrome — bank.c's own legend
 * ("Number in bank in green", "Number held in blue"), {@code surface_draw_item_grid} for which
 * corner each number sits in, and the inventory tab's red slot for what is being worn.
 */
export interface PackItem {
    id: number;
    /** How many are in the pack. */
    held: number;
    /** How many are in the bank. */
    banked: number;
    worn: boolean;
}

export function PackWindow({items, names}: {
    items: PackItem[];
    /** Item id → display name, for the slot's tooltip. */
    names: Record<string, string> | null;
}) {
    const [atlas, setAtlas] = useState<ItemAtlasIndex | null>(null);
    // Worn first, as the game's inventory keeps what is on the body at the top.
    const carried = items.filter(i => i.held > 0)
        .sort((a, b) => Number(b.worn) - Number(a.worn));
    const banked = items.filter(i => i.held === 0);
    const slot = (item: PackItem) => (
        <div key={item.id} className={item.worn ? "pack-slot worn" : "pack-slot"}
             title={names?.[String(item.id)] ?? `item ${item.id}`}>
            <ItemIcon atlas={atlas} id={item.id} box={30}/>
            {item.banked > 0 && <span className="pack-in-bank">{amount(item.banked)}</span>}
            {item.held > 0 && <span className="pack-held">{amount(item.held)}</span>}
        </div>
    );
    useEffect(() => {
        let alive = true;
        getItemAtlas().then(a => alive && setAtlas(a));
        return () => {
            alive = false;
        };
    }, []);
    return (
        <aside className="pack">
            <header className="pack-head">
                <span>bank &amp; inventory</span>
                <span className="pack-legend">
                    <em className="pack-in-bank">bank</em> <em className="pack-held">held</em>
                </span>
            </header>
            <div className="pack-grid">
                {carried.map(slot)}
                {/* What it carries, then what only the bank holds — a trip's difference, which is
                    what a bank stop is for. */}
                {carried.length > 0 && banked.length > 0 && <hr className="pack-rule"/>}
                {banked.map(slot)}
                {items.length === 0 && <span className="pack-empty">nothing carried or banked</span>}
            </div>
        </aside>
    );
}

/** The client's own shortening: thousands as {@code 12K}, millions as {@code 3M}. */
function amount(n: number): string {
    if (n >= 10_000_000) return `${Math.floor(n / 1_000_000)}M`;
    if (n >= 100_000) return `${Math.floor(n / 1000)}K`;
    return String(n);
}
