import * as THREE from "three";
import {freezeTransform} from "./staticTransform";
import {Ribbon} from "./World3DSight";
import {TagPool, type TagStyle, type ViewSize} from "./World3DTags";

/**
 * Overlays — decoration an embedder adds to the scene without forking the viewer.
 *
 * The view draws the world and the things the game defines. Anything a particular deployment
 * cares about — a squad's no-go boxes, a raid's markers, whatever the next idea is — is an
 * overlay: it gets the frame, the coordinate transform, and the two primitives that are annoying
 * to rebuild correctly (draped outlines and pooled labels), and nothing else.
 *
 * The library's own draped decoration is built on this same interface, deliberately: an
 * extension point nothing internal depends on drifts away from what its users need.
 */

/**
 * Draw bands, as `renderOrder` within the transparent pass. Passing a raw number instead is
 * possible and unwise: the sprite layers hold 11–13, so a guessed number lands in the middle of
 * the characters. Note renderOrder only sorts WITHIN a pass — an opaque object beats every
 * transparent one regardless — which is why everything here is transparent.
 */
export const OVERLAY_BAND = {
    /** Draped on the terrain, under the characters standing on it. Where a zone outline belongs. */
    ground: 9,
    /** Over ground decoration, still under the characters. */
    aboveGround: 10,
    /** Over everything, projectiles included. Use sparingly — it hides the world. */
    chrome: 15,
} as const;

export type OverlayBand = keyof typeof OVERLAY_BAND;

/** A point on the ground, for hit-testing. `z` is ABSOLUTE, as it arrives from the server. */
export interface OverlayPoint {
    x: number;
    z: number;
    floor: number;
    world: THREE.Vector3;
}

/**
 * What an overlay is handed every frame. Fields are refreshed in place, so hold the context if you
 * like but read it fresh — and never hold a value out of it across frames.
 */
export interface OverlayContext {
    /** This overlay's own group. Everything it adds goes here, and is removed with it. Already
     *  excluded from the pick pass, so overlay geometry can never occlude a click on the world. */
    group: THREE.Group;
    camera: THREE.Camera;
    /** The floor being shown (0 ground · 1,2 upper · 3 underground). Filtering to it is the
     *  overlay's job — nothing else knows which of your data belongs to which floor. */
    floor: number;
    /**
     * Tile → world point with terrain height folded in. Takes ABSOLUTE z, the form data arrives
     * in, so an overlay never does floor arithmetic.
     *
     * Returns a fresh vector, or fills `out` and returns that. Pass one when the call is per
     * entity per frame — a label layer can run the whole frame off a single scratch vector, since
     * {@link TagPool.put} projects the point and keeps nothing.
     */
    toWorld(x: number, z: number, out?: THREE.Vector3): THREE.Vector3;
    /**
     * Bumped when the terrain under the view has SETTLED at a new shape. Anything draped has to be
     * rebuilt when it changes. It deliberately isn't the raw streaming revision: cells arrive in a
     * trickle, and redraping on each would rebuild the same ribbon dozens of times for one pan.
     */
    heightsRev: number;
    /** View height in tiles — the zoom gate. Hide detail when this gets large. */
    zoomTiles: number;
    /** Screen size, measured once per frame before anything writes a style. */
    view: ViewSize;
    /** A pooled label layer, owned by this overlay and disposed with it. Make one per style, at
     *  mount, not per frame. Set `interactive` and its `onClick` to make labels clickable. */
    tags(style: TagStyle): TagPool;
    /** A draped outline, owned by this overlay and disposed with it. */
    ribbon(opts: {color: number; opacity: number; ghostOpacity: number;
                  band?: OverlayBand}): Ribbon;
}

/**
 * One overlay. `frame` runs every frame, so it does its own dirty-checking — only the overlay
 * knows which of its work is expensive.
 *
 * Interaction, if any, is split on purpose. Hover is broadcast: every overlay whose `hitTest`
 * matches the cursor is told, because a character standing inside a zone must not stop the zone
 * highlighting. Clicks are NOT part of this interface — put them on a label, by making its pool
 * interactive. Geometry that swallows clicks is a hole in the world underneath it, and a zone is
 * large enough that the hole would eat most of the walkable surface it covers.
 */
export interface ViewerOverlay<T = unknown> {
    /** Called once when the overlay appears, before its first frame. */
    mount?(ctx: OverlayContext): void;
    frame(ctx: OverlayContext, data: T): void;
    /**
     * The ground point under the cursor → a key identifying what it landed on, or null. Pure CPU:
     * it runs against a point the view has already resolved, so a rectangle test costs nothing.
     *
     * A key rather than an object, because the key IS the identity: hover fires when it changes,
     * so anything that should count as a different hover has to be in the string. Something with
     * parts puts them there (`"zone3/grip-nw"`). Anything else is a lookup in `data`, which
     * {@link hover} is handed anyway.
     */
    hitTest?(at: OverlayPoint, data: T): string | null;
    /** This overlay's current hover key, or null the frame the cursor leaves it. */
    hover?(hit: string | null, ctx: OverlayContext, data: T): void;
    /** Called when the overlay is removed. Its group, tag pools and ribbons are torn down for it;
     *  this is for anything else it holds. */
    dispose?(): void;
}

/**
 * An overlay as passed to the view: a STABLE implementation plus this render's data.
 *
 * The split is what keeps `overlays={[…]}` from thrashing. A fresh array of fresh objects every
 * render is the natural thing to write in React, and would otherwise mean mount/dispose per frame;
 * keyed by `id`, only add and remove are lifecycle events, and `data` is just an argument.
 *
 * Opaque, and built only by {@link overlay}: the array is heterogeneous, so an entry type that
 * exposed its data would have to be loose enough to let one overlay's impl be paired with
 * another's. Binding the pair in `overlay()` checks it where it is written.
 */
export interface OverlayEntry {
    readonly id: string;
    readonly impl: ViewerOverlay<unknown>;
    readonly data: unknown;
}

/** Pair an implementation with its data, checked. The only way to build an {@link OverlayEntry}. */
export function overlay<T>(id: string, impl: ViewerOverlay<T>, data: T): OverlayEntry {
    return {id, impl: impl as ViewerOverlay<unknown>, data};
}

/**
 * The redrape gate: true when anything a draped overlay's geometry depends on has changed.
 *
 * `frame` runs every frame, so every overlay that drapes needs this check. Terrain height is
 * baked into a ribbon's vertices at extrude time, which is what puts
 * {@link OverlayContext.heightsRev} in here beside the data and the floor.
 *
 *     const stale = drapeGate();
 *     frame(ctx, data) {
 *         if (!stale(ctx, data)) return;
 *         …
 *     }
 *
 * One gate per thing that redraws on its own schedule — labels that follow the camera every frame
 * are not behind it.
 *
 * A remount is a change too. An overlay object outlives its mount (a toggle unmounts and remounts
 * the same one), the host disposes its ribbons in between, and each mount has a context of its own:
 * without the context in here, a remount handed the same data as before drew nothing into its new
 * ribbon (the cluster grid ticked off and on came back with its numbers and no lines).
 */
export function drapeGate(): (ctx: OverlayContext, data: unknown) => boolean {
    // Not null/undefined: either is a legitimate first value, and starting equal to one would skip
    // the frame that first drew it.
    let lastCtx: OverlayContext | null = null;
    let lastData: unknown = UNSET;
    let lastFloor = Number.NaN;
    let lastHeights = Number.NaN;
    return (ctx, data) => {
        if (ctx === lastCtx && data === lastData && ctx.floor === lastFloor
            && ctx.heightsRev === lastHeights) {
            return false;
        }
        lastCtx = ctx;
        lastData = data;
        lastFloor = ctx.floor;
        lastHeights = ctx.heightsRev;
        return true;
    };
}

const UNSET = Symbol("unset");

/**
 * A tile box's OUTER edges: corners ordered, and the half-tile margin folded in.
 *
 * `toWorld` addresses tile CENTRES, so an outline traced through x0..x1 sits half a tile inside the
 * box on every side and under-draws what the box actually covers. Every consumer of a tile box
 * needs the same four numbers — the outline that drapes it, and anything placed on its edges — so
 * the convention lives here rather than being restated at each of them.
 */
export function boxEdges(box: {x0: number; z0: number; x1: number; z1: number}):
    {x0: number; z0: number; x1: number; z1: number} {
    return {
        x0: Math.min(box.x0, box.x1) - 0.5,
        x1: Math.max(box.x0, box.x1) + 0.5,
        z0: Math.min(box.z0, box.z1) - 0.5,
        z1: Math.max(box.z0, box.z1) + 0.5,
    };
}

/**
 * The perimeter of a tile box, as points to drape.
 *
 * Not four corners: {@link Ribbon.extrude} interpolates in a straight line between the vertices it
 * is given, so a box described by its corners cuts through every hill along an edge. Walking it
 * tile by tile keeps the outline on the ground.
 *
 * Traced along {@link boxEdges}, so it hugs the outer edge of what the box covers. Long edges are
 * strided, so a huge box costs a bounded number of vertices rather than one per tile.
 */
export function boxPerimeter(box: {x0: number; z0: number; x1: number; z1: number},
                             maxPoints = 512): {x: number; z: number}[] {
    const {x0, x1, z0, z1} = boxEdges(box);
    const stride = Math.max(1, Math.ceil((2 * (x1 - x0 + z1 - z0) + 4) / maxPoints));
    const pts: {x: number; z: number}[] = [];
    for (let x = x0; x < x1; x += stride) pts.push({x, z: z0});
    for (let z = z0; z < z1; z += stride) pts.push({x: x1, z});
    for (let x = x1; x > x0; x -= stride) pts.push({x, z: z1});
    for (let z = z1; z > z0; z -= stride) pts.push({x: x0, z});
    if (pts.length < 2) pts.push({x: x0, z: z0}, {x: x1, z: z1});
    return pts;
}

/** Per-overlay bookkeeping: its group, its context, and the resources it made through that. */
interface Slot {
    impl: ViewerOverlay<unknown>;
    ctx: OverlayContext;
    group: THREE.Group;
    tags: TagPool[];
    ribbons: Ribbon[];
    /** The hit key reported last time, to tell a hover change from a hover repeat. */
    hover: string | null;
}

/** Frame-varying half of the context, refreshed once and shared by every overlay. */
export interface OverlayFrame {
    floor: number;
    heightsRev: number;
    zoomTiles: number;
    view: ViewSize;
    /** Tile → world, taking ABSOLUTE z, optionally into `out`. */
    toWorld(x: number, z: number, out?: THREE.Vector3): THREE.Vector3;
}

/**
 * Keeps the mounted overlays in step with the `overlays` prop, and runs them.
 *
 * Owned by the render loop: `sync` each frame, `hover` when the cursor's ground point changes,
 * `dispose` on teardown.
 */
export class OverlayHost {
    private readonly slots = new Map<string, Slot>();
    /** Overlays whose draw has thrown, so each is logged once rather than every frame. */
    private readonly failed = new Set<string>();

    constructor(private readonly scene: THREE.Scene,
                private readonly camera: THREE.Camera,
                private readonly tagHost: HTMLElement) {}

    /** Mount/unmount to match `entries`, then frame each in array order. */
    sync(entries: readonly OverlayEntry[], frame: OverlayFrame): void {
        for (const [id, slot] of this.slots) {
            if (!entries.some(e => e.id === id)) {
                this.drop(id, slot);
            }
        }
        for (const entry of entries) {
            let slot = this.slots.get(entry.id);
            if (slot && slot.impl !== entry.impl) {
                // Same id, different implementation: a remount, not an update.
                this.drop(entry.id, slot);
                slot = undefined;
            }
            if (!slot) {
                slot = this.mount(entry);
                // Refreshed BEFORE mount: mount runs with the first frame's context.
                this.refresh(slot, frame);
                slot.impl.mount?.(slot.ctx);
            }
            this.refresh(slot, frame);
            // One overlay's failure is its own: thrown through, it skipped every overlay after it
            // for the frame, and those that had already taken the new data then drew it never.
            try {
                slot.impl.frame(slot.ctx, entry.data);
            } catch (e) {
                if (!this.failed.has(entry.id)) {
                    this.failed.add(entry.id);
                    console.error(`[overlay] ${entry.id} failed to draw:`, e);
                }
            }
        }
    }

    /**
     * Broadcast the cursor's ground point. Every overlay that claims it is told, and every overlay
     * that claimed it last time and doesn't now is told null — so an overlay never has to work out
     * that it stopped being hovered.
     */
    hover(at: OverlayPoint | null, entries: readonly OverlayEntry[]): void {
        for (const entry of entries) {
            const slot = this.slots.get(entry.id);
            if (!slot?.impl.hover) continue;
            const hit = at && slot.impl.hitTest ? slot.impl.hitTest(at, entry.data) : null;
            if (hit === slot.hover) continue;
            slot.hover = hit;
            slot.impl.hover(hit, slot.ctx, entry.data);
        }
    }

    dispose(): void {
        for (const [id, slot] of this.slots) this.drop(id, slot);
    }

    private mount(entry: OverlayEntry): Slot {
        const group = new THREE.Group();
        // Top-level and flagged: the pick pass hides flagged top-level children wholesale, so
        // nothing an overlay draws can occlude the world's own id/depth buffers.
        group.userData.noPick = true;
        this.scene.add(freezeTransform(group));
        const slot: Slot = {
            impl: entry.impl,
            group,
            tags: [],
            ribbons: [],
            hover: null,
            ctx: {
                group,
                camera: this.camera,
                floor: 0,
                heightsRev: -1,
                zoomTiles: 0,
                view: {w: 0, h: 0},
                toWorld: (_x, _z, out) => out ?? new THREE.Vector3(),
                tags: (style: TagStyle) => {
                    const pool = new TagPool(this.tagHost, style);
                    slot.tags.push(pool);
                    return pool;
                },
                ribbon: opts => {
                    const r = new Ribbon(group, opts.color, opts.opacity, opts.ghostOpacity);
                    r.band = OVERLAY_BAND[opts.band ?? "ground"];
                    slot.ribbons.push(r);
                    return r;
                },
            },
        };
        this.slots.set(entry.id, slot);
        return slot;
    }

    private refresh(slot: Slot, frame: OverlayFrame): void {
        slot.ctx.floor = frame.floor;
        slot.ctx.heightsRev = frame.heightsRev;
        slot.ctx.zoomTiles = frame.zoomTiles;        slot.ctx.view = frame.view;
        slot.ctx.toWorld = frame.toWorld;
    }

    private drop(id: string, slot: Slot): void {
        slot.impl.dispose?.();
        for (const pool of slot.tags) pool.dispose();
        for (const r of slot.ribbons) r.dispose();
        this.scene.remove(slot.group);
        this.slots.delete(id);
    }
}
