import {useEffect, useState} from "react";
import {fetchWearables} from "./api";
import {wornItems} from "./World3DView";

/** The kinds of thing the view itself reports a pick for. */
export type PickKind = "player" | "bot" | "npc" | "object" | "boundary";

/** What a click in the world landed on, as reported by `World3DView.onPickEntity`.
 *  `null` there means the click hit nothing, so whatever card is open should close. */
export interface PickedEntity {
    /**
     * What was picked. Any string is allowed, not just {@link PickKind}: picks are reported to the
     * embedder rather than drawn, so an overlay that wants its own click to open the same card
     * simply calls the same setter with a kind of its own — the demo's region overlay reports
     * `"region"`. The union is there for autocomplete on the five the view produces.
     */
    kind: PickKind | (string & {});
    /** Display name, or null when the entity has none yet (a player whose
     *  appearance hasn't landed) or carries only a definition id. */
    name: string | null;
    /** Definition id for npcs/scenery/boundaries; null for players. */
    npcId: number | null;
    inCombat: boolean;
    /** Players only — the RSC appearance token, which names the worn items below. */
    appearance?: string | null;
}

/**
 * A minimal info card for a pick: name, kind, and what the entity is wearing.
 *
 * The view itself renders no card — it reports the pick and leaves the decision of what to show,
 * where, to whoever embeds it. This is the default one, for an embedder that wants a card without
 * writing one; a UI with its own visual language should build its own and read {@link wornItems}
 * (exported for exactly that) instead of restyling this.
 *
 * Self-contained on purpose: it fetches the sprite→item-name map itself, so rendering it costs one
 * piece of state (the pick) and nothing else. An embedder already holding that map from
 * {@link fetchWearables} can pass it in and skip the fetch.
 */
export function EntityCard({pick, onClose, wearables}: {
    pick: PickedEntity;
    onClose: () => void;
    /** The sprite→item-name map, if you already have one. Fetched on mount otherwise. */
    wearables?: Record<number, string[]> | null;
}) {
    const [fetched, setFetched] = useState<Record<number, string[]> | null>(null);
    useEffect(() => {
        if (wearables !== undefined) return;
        let live = true;
        fetchWearables().then(w => live && setFetched(w)).catch(() => {});
        return () => {
            live = false;
        };
    }, [wearables]);
    const worn = pick.appearance
        ? wornItems(pick.appearance, wearables !== undefined ? wearables : fetched)
        : null;
    return (
        <div style={{
            minWidth: 180, pointerEvents: "auto",
            background: "rgba(16,16,26,.92)", padding: "8px 12px",
            borderRadius: 8, fontSize: 13, fontFamily: "monospace",
            border: "1px solid #3a4664",
        }}>
            <div style={{display: "flex", justifyContent: "space-between", gap: 12}}>
                <b>{pick.name ?? `${pick.kind} #${pick.npcId ?? "?"}`}</b>
                <span style={{cursor: "pointer", opacity: .7}} onClick={onClose}>✕</span>
            </div>
            <div style={{opacity: .85, marginTop: 4}}>
                {pick.kind}
                {pick.npcId != null ? ` · id ${pick.npcId}` : ""}
                {pick.inCombat ? " · in combat" : ""}
            </div>
            {worn && (
                <div style={{marginTop: 6, borderTop: "1px solid #3a4664",
                             paddingTop: 6, maxWidth: 260}}>
                    {worn.map(w => (
                        <div key={w.slot} style={{display: "flex", gap: 8, lineHeight: "18px"}}>
                            <span style={{opacity: .55, width: 52, flexShrink: 0}}>{w.slot}</span>
                            <span>{w.names}</span>
                        </div>
                    ))}
                    {worn.length === 0 && <div style={{opacity: .55}}>nothing equipped</div>}
                </div>
            )}
        </div>
    );
}
