/**
 * The route planner: a floating, draggable panel that plans a route AS an account — its levels,
 * quests, pack and bank — carrying a loadout.
 *
 * <p>It asks only what can change a route, because the server derives the whole editor from the
 * transport gates ({@link PlannerHost#inputs}): the skills some gate reads, each slider snapping
 * to the levels where an answer actually changes, the item families a gate accepts interchangeably as
 * ONE row, and single items ordered by how many transports ask for them. Anything else is noise —
 * firemaking changes no route, and six pickaxe rows crowd out the coins row that matters.
 *
 * <p>Combat level is one slider rather than seven stats: nothing but the danger rung reads
 * attack/strength/defense/hits, so the panel synthesizes stats that hit the asked level. Its minimum
 * follows from the gated skills, since a magic-51 account cannot be combat 3.
 *
 * <p>Every row carries three amounts — what is in the pack, what is in the BANK, and what to arrive
 * holding — which is what makes the banker demonstrable: an item banked and wanted on arrival puts a
 * stop on the route, and the answer says the stop is there for the loadout.
 */

/** A row in the item table: a single item, or a family the gates accept interchangeably. */
export type PlannerRow = { kind: "item"; id: number } | { kind: "group"; label: string };

/** Per-row amounts are keyed by this, so a family and an item can share the tables. */
export function rowKey(row: PlannerRow): string {
    return row.kind === "item" ? `i${row.id}` : `g${row.label}`;
}

/** Everything the editor holds. Owned by the app so a change can re-plan. */
export interface PlannerRequestState {
    /** Gate skills as set; the combat feeders are synthesized from {@link #combatLevel}. */
    levels: Levels;
    combatLevel: number;
    rows: PlannerRow[];
    inventory: Record<string, number>;
    bank: Record<string, number>;
    arrive: Record<string, number>;
    /** Rows to arrive WEARING — the loadout's worn flag; the walker puts them on at the last stop. */
    equip: Record<string, boolean>;
    quests: Record<number, number>;
    /** Known player-cache values by server key; a key not here is unknown. */
    cache: Record<string, boolean | number>;
    policy: NavPolicy;
}

const DEFAULT_POLICY: NavPolicy = {
    // Off by default: the plain shortest walk is the baseline a plan is read against; danger
    // avoidance is the thing to switch on and compare.
    danger: "OFF",
    teleportSpells: false,
    teleportJewellery: false,
    costOverrides: {},
    assumeAllEligible: false,
    avoidSkulled: true,
    // A bot always keeps its distance from the aggressive NPCs it sees; the walk does too.
    berth: {berthByDefault: true, ids: [], indexes: []},
};

/** The routing checkboxes, by the catalogue key each one publishes: the knob it reads and sets. */
const POLICY_FLAGS: Record<string, {
    get(p: NavPolicy): boolean;
    set(p: NavPolicy, on: boolean): NavPolicy;
}> = {
    danger: {
        get: p => p.danger === "ON",
        set: (p, on) => ({...p, danger: on ? "ON" : "OFF"}),
    },
    berth: {
        get: p => p.berth.berthByDefault,
        set: (p, on) => ({...p, berth: {berthByDefault: on, ids: [], indexes: []}}),
    },
    teleportSpells: {
        get: p => p.teleportSpells,
        set: (p, on) => ({...p, teleportSpells: on}),
    },
    teleportJewellery: {
        get: p => p.teleportJewellery,
        set: (p, on) => ({...p, teleportJewellery: on}),
    },
};

/**
 * `raw` as a whole policy: the defaults under whatever it states. A link shared before the request
 * carried a `NavPolicy` holds `{avoidDanger, teleportSpells, teleportJewellery}`, read as such.
 */
export function policyOf(raw: unknown): NavPolicy {
    if (typeof raw !== "object" || raw == null) return DEFAULT_POLICY;
    const o = raw as Partial<NavPolicy> & {avoidDanger?: boolean};
    const out: NavPolicy = {...DEFAULT_POLICY, ...o};
    if (o.danger == null && typeof o.avoidDanger === "boolean") {
        out.danger = o.avoidDanger ? "ON" : "OFF";
    }
    delete (out as {avoidDanger?: boolean}).avoidDanger;
    out.berth = {...DEFAULT_POLICY.berth, ...(o.berth ?? {})};
    return out;
}

/**
 * The rows every plan starts with, in the order a person asks about kit — coins, then the tools a
 * gate might want. NOT by reach: that put "an axe" on top because Karamja has hundreds of jungle
 * tiles, which is nobody's idea of the most important row. Each starts with a little of it BANKED,
 * so the first plan already has something to bank for.
 */
const STANDING_ROWS: { group?: string; item?: string; bank: number }[] = [
    {item: "Coins", bank: 100},
    {group: "a knife or a melee weapon", bank: 1},
    {group: "a lit light source", bank: 1},
    {group: "an axe", bank: 1},
    {item: "Machette", bank: 1},
];

/** The standing rows, resolved against the declarations; anything the registry doesn't know is
 *  skipped rather than shown as a dead row. */
export function defaultRows(inputs: PlannerInputs | null): PlannerRow[] {
    if (!inputs) return [];
    const rows: PlannerRow[] = [];
    for (const want of STANDING_ROWS) {
        if (want.group) {
            const group = inputs.itemGroups.find((g) => g.label === want.group);
            if (group) rows.push({kind: "group", label: group.label});
        } else {
            const item = inputs.items.find(
                (i) => i.name.toLowerCase() === want.item!.toLowerCase());
            if (item) rows.push({kind: "item", id: item.id});
        }
    }
    return rows;
}

/** Whether a row is one of the standing ones — those stay put, so they carry no remove button. */
export function isStandingRow(row: PlannerRow, inputs: PlannerInputs | null): boolean {
    const key = rowKey(row);
    return defaultRows(inputs).some((r) => rowKey(r) === key);
}

export function freshState(inputs: PlannerInputs | null): PlannerRequestState {
    const levels = freshLevels(inputs);
    const rows = defaultRows(inputs);
    const bank: Record<string, number> = {};
    rows.forEach((row, i) => {
        bank[rowKey(row)] = STANDING_ROWS[i]?.bank ?? 0;
    });
    return {
        levels,
        combatLevel: combatLevelOf(levels),
        rows,
        inventory: {},
        bank,
        arrive: {},
        equip: {},
        quests: {},
        cache: {},
        policy: DEFAULT_POLICY,
    };
}

/**
 * {@code state} as a maxed account: every skill at 99 (combat 123) and every quest a gate reads
 * done. The pack, bank and routing choices stay as they were.
 */
export function maxedState(state: PlannerRequestState,
                           inputs: PlannerInputs | null): PlannerRequestState {
    const levels = {...state.levels};
    for (const name of Object.keys(levels)) levels[name] = SKILL_MAX;
    const quests: Record<number, number> = {};
    for (const q of inputs?.quests ?? []) quests[q.id] = -1;
    return {...state, levels, combatLevel: 123, quests};
}

/**
 * A family's label as a ROW reads: the gates' prose ("a knife or a melee weapon") is right in a
 * sentence and wrong in a table, where every row would start with an article.
 */
export function familyLabel(label: string): string {
    const stripped = label.replace(/^an? /, "").replace(/ or an? /, " or ");
    return stripped.charAt(0).toUpperCase() + stripped.slice(1);
}

/**
 * A skill as a LABEL. The API publishes the server's own enum name (`WOODCUTTING`) because that is
 * what the plan request takes back; a column of shouting is not what the stats screen this mirrors
 * looks like.
 */
export function skillLabel(skill: string): string {
    return skill.charAt(0) + skill.slice(1).toLowerCase();
}

/**
 * The stages of {@code quest} worth offering: not started, every stage some gate tests, and done.
 * Nothing between them changes a route, so nothing between them is offered.
 */
function questStages(quest: { atLeast: { at: number }[]; exact: { at: number }[] }): number[] {
    const stages = new Set<number>([0, -1]);
    for (const t of quest.atLeast) stages.add(t.at);
    for (const t of quest.exact) stages.add(t.at);
    // done (−1) last: it is the end of the quest, not a stage before its first.
    return [...stages].sort((a, b) => (a === -1 ? 1 : b === -1 ? -1 : a - b));
}

/** A stage as a label: 0 is untouched, −1 is finished, anything else is a numbered rung. */
function stageLabel(stage: number): string {
    return stage === -1 ? "done" : stage === 0 ? "not started" : `stage ${stage}`;
}

/** The item ids a row stands for; a family's first member is its best tier. */
/** Whether a row names something that can be WORN — a family's best tier stands for it. */
function wearable(row: PlannerRow, inputs: PlannerInputs | null,
                  wearables: ReadonlySet<number> | null | undefined): boolean {
    return wearables != null && rowItems(row, inputs).some((id) => wearables.has(id));
}

export function rowItems(row: PlannerRow, inputs: PlannerInputs | null): number[] {
    if (row.kind === "item") return [row.id];
    const group = inputs?.itemGroups.find((g) => g.label === row.label);
    return group ? group.items.map((i) => i.id) : [];
}

/**
 * The rows a failed plan blames, by {@link rowKey}. A blocker names the item ids it covers rather
 * than a row — the planner knows nothing of this editor's rows — so a row is the culprit when its
 * own ids meet them. A family row matches on any tier, which is right: the band was stated over
 * the family.
 */
export function blockedRows(plan: PlanResponse | null, rows: PlannerRow[],
                            inputs: PlannerInputs | null): ReadonlySet<string> {
    const blocked = new Set<string>();
    if (!plan || plan.found || !plan.why) return blocked;
    const blamed = new Set<number>();
    for (const b of plan.why.blockers) for (const id of b.items) blamed.add(id);
    if (blamed.size === 0) return blocked;
    for (const row of rows) {
        if (rowItems(row, inputs).some((id) => blamed.has(id))) blocked.add(rowKey(row));
    }
    return blocked;
}

/** The editor's known cache values as the request's two typed maps. */
export function cacheValuesOf(cache: Record<string, boolean | number>): PlanCacheValues {
    const out: PlanCacheValues = {bools: {}, ints: {}};
    for (const [key, v] of Object.entries(cache)) {
        if (typeof v === "boolean") out.bools[key] = v;
        else out.ints[key] = v;
    }
    return out;
}

/** The editor as a plan request: amounts become a pack and a bank, arrivals become wants. */
/**
 * The editor as a plan request. {@code as} is for the WALK tool, which plans as a real bot; the
 * panel itself always plans as the account described here — picking a bot COPIES it in rather than
 * planning by reference, so every value stays editable afterwards.
 */
export function toPlanRequest(state: PlannerRequestState, inputs: PlannerInputs | null,
                             from: { x: number; z: number },
                             to: { x: number; z: number },
                             as: string | null = null): PlanRequest {
    const inventory: Record<number, number> = {};
    const bank: Record<number, number> = {};
    const wants: PlanWant[] = [];
    for (const row of state.rows) {
        const key = rowKey(row);
        const ids = rowItems(row, inputs);
        if (ids.length === 0) continue;
        const inv = state.inventory[key] ?? 0;
        const banked = state.bank[key] ?? 0;
        const arrive = state.arrive[key] ?? 0;
        // A family's amounts go on its best tier — the one a bank stop would reach for anyway.
        if (inv > 0) inventory[ids[0]] = inv;
        if (banked > 0) bank[ids[0]] = banked;
        if (arrive > 0) {
            const worn = state.equip?.[key] === true ? {worn: true} : {};
            wants.push(row.kind === "item"
                ? {item: ids[0], min: arrive, target: arrive, max: arrive, ...worn}
                : {anyOf: ids, min: arrive, target: arrive, max: arrive, ...worn});
        }
    }
    return {
        from,
        to,
        as,
        account: {
            skills: requestLevels(state.levels, state.combatLevel),
            quests: state.quests,
            inventory,
            bank,
            cache: cacheValuesOf(state.cache),
        },
        loadout: {
            // The arrive column is the WHOLE target loadout, not a floor. Anything carried that it
            // does not name is banked on the way, which is the point of stating a loadout at all;
            // sending true quietly turned every plan into "this, plus whatever you happen to hold".
            keepEverythingElse: false,
            bankWhenFull: false,
            wants,
        },
        policy: policyOf(state.policy),
    };
}

/** Whether a host can answer yet: ready, still starting, or failed with a reason. */
export type PlannerHostState = "ready" | "loading" | { failed: string };

/** An account the editor can be filled from. */
export interface PlannerCopySource {
    value: string;
    label: string;
}

export interface PlannerPanelProps {
    /** Who answers the account breakdown. */
    host: PlannerHost;
    /**
     * Whether the host can answer yet. `loading` while it starts (the in-page pathfinder takes a
     * few seconds to load its world); a string says why it cannot. Omitted means ready.
     */
    hostState?: PlannerHostState;
    /** While `loading`: what the host is doing right now, if it says. */
    hostProgress?: string | null;
    inputs: PlannerInputs | null;
    /** Accounts "plan as" can copy from, besides the fresh and maxed presets; `value` goes to
     *  {@link #onCopyFrom}. */
    copySources: PlannerCopySource[];
    itemDefs: ItemNames | null;
    /** The ids that may be WORN, so the wear column is only offered where it means something;
     *  absent while the host has not said, which offers it for nothing. */
    wearableItems?: ReadonlySet<number> | null;
    start: { x: number; z: number } | null;
    end: { x: number; z: number } | null;
    /** Map clicks are setting the endpoints. */
    picking: boolean;
    /** Drop both endpoints and arm the pick again. */
    onClearRoute: () => void;
    /** Ask the same question again — to watch the caches warm. */
    onReplan: () => void;
    /** Whether the camera follows the bot walking the plan; the checkbox shows only when the host
     *  has such a bot and passes {@link #onFollowChange}. */
    follow?: boolean;
    onFollowChange?: (on: boolean) => void;
    /** Which endpoint the next map click sets, when one was singled out. */
    pickTarget: "start" | "end" | null;
    /** Single out an endpoint for the next click (and turn picking on). */
    onArmEndpoint: (which: "start" | "end") => void;
    /** Set one endpoint outright — a typed coordinate. */
    onSetEndpoint: (which: "start" | "end", tile: { x: number; z: number }) => void;
    state: PlannerRequestState;
    onStateChange: (next: PlannerRequestState) => void;
    plan: PlanResponse | null;
    loading: boolean;
    error: string | null;
    /** Highlight a step's tile on the map (null clears). */
    onHoverStep: (tile: { x: number; z: number } | null) => void;
    /** Put a step's own tile in the middle of the map — whichever map is up. */
    onFocusStep: (tile: { x: number; z: number }) => void;
    /** Fill the editor from a preset ("fresh"/"maxed") or a named account — a one-time copy. */
    onCopyFrom: (choice: string) => void;
    onClose: () => void;
    /**
     * The walking components this account can reach from the start, while the panel's
     * "reachable" toggle is on; null when it is off, the start is unset, or the panel closes. The
     * host draws the components layer with only these. Omitted, the toggle is not offered.
     */
    onReachable?: (ids: ReadonlySet<number> | null) => void;
}

/**
 * The "reachable" toggle's state: asked of the host whenever the start or the account changes
 * while it is on, and handed out through {@link PlannerPanelProps.onReachable}.
 */
function useReachable(props: PlannerPanelProps, on: boolean) {
    const {host, inputs, start, state, onReachable} = props;
    const [info, setInfo] = useState<{count: number; total: number; ms: number} | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    useEffect(() => {
        if (!onReachable) return;
        if (!on || !start) {
            onReachable(null);
            setInfo(null);
            setError(null);
            return;
        }
        let alive = true;
        setLoading(true);
        host.reachable(toPlanRequest(state, inputs, start, start)).then(
            (r) => {
                if (!alive) return;
                setLoading(false);
                setError(null);
                setInfo({count: r.reachable.length, total: r.components, ms: r.ms});
                onReachable(new Set(r.reachable));
            },
            (e) => {
                if (!alive) return;
                setLoading(false);
                setError(e instanceof Error ? e.message : String(e));
                onReachable(null);
            });
        return () => {
            alive = false;
        };
    }, [host, inputs, start, state, on, onReachable]);
    // Closing the panel takes the filter with it.
    useEffect(() => () => onReachable?.(null), [onReachable]);
    return {info, error, loading};
}

export function PlannerPanel(props: PlannerPanelProps) {
    const {inputs, copySources, itemDefs, start, end, picking, state, onStateChange, plan} = props;
    const hostState = props.hostState ?? "ready";
    const [stored, setPos] = useStoredState("planner.panel.pos", {x: 88, y: 84});
    const drag = useRef<{ dx: number; dy: number } | null>(null);
    const panel = useRef<HTMLElement>(null);
    const [search, setSearch] = useState("");
    const [reachOn, setReachOn] = useState(false);
    const reach = useReachable(props, reachOn);
    // The panel is kept on screen where it is DRAWN, not only where it is dropped: a window made
    // smaller (or a position stored by a bigger one) would otherwise leave it out of reach. The
    // stored position stays as dragged, so making the window bigger again puts it back.
    const [, setViewport] = useState(0);
    useEffect(() => {
        const onResize = () => setViewport((n) => n + 1);
        onResize(); // once measured: the first draw only had a guess at the panel's size
        window.addEventListener("resize", onResize);
        return () => window.removeEventListener("resize", onResize);
    }, []);
    const onScreen = (p: {x: number; y: number}) => {
        const w = panel.current?.offsetWidth ?? 200;
        const h = panel.current?.offsetHeight ?? 60;
        return {
            x: Math.max(0, Math.min(window.innerWidth - w, p.x)),
            y: Math.max(0, Math.min(window.innerHeight - h, p.y)),
        };
    };
    const pos = onScreen(stored);

    const set = (patch: Partial<PlannerRequestState>) => onStateChange({...state, ...patch});
    const nameOf = (id: number) => itemDefs?.[String(id)] ?? `item#${id}`;
    // The rows a failed plan blames, so the verdict above the table and the rows in it are the
    // same statement — reading "the loadout forbids all of them" and then hunting eight rows for
    // the one it meant was the whole complaint.
    const blocked = blockedRows(plan, state.rows, inputs);

    const onPointerDown = (e: React.PointerEvent) => {
        drag.current = {dx: e.clientX - pos.x, dy: e.clientY - pos.y};
        (e.target as HTMLElement).setPointerCapture(e.pointerId);
    };
    const onPointerMove = (e: React.PointerEvent) => {
        if (!drag.current) return;
        setPos(onScreen({x: e.clientX - drag.current.dx, y: e.clientY - drag.current.dy}));
    };
    const onPointerUp = () => {
        drag.current = null;
    };

    const gateSkills = useMemo(
        () => (inputs?.skills ?? []).filter((s) => s.breakpoints.length > 0),
        [inputs],
    );
    const combatFloor = minCombatLevel(state.levels);

    return (
        <aside className="planner" ref={panel} style={{left: pos.x, top: pos.y}}>
            <header className="planner-head" onPointerDown={onPointerDown}
                    onPointerMove={onPointerMove} onPointerUp={onPointerUp}>
                <span>route planner</span>
                <button type="button" className="planner-close" onClick={props.onClose}
                        title="close">×</button>
            </header>

            <div className="planner-body">
                {/* Nothing to edit until the host answers: the editor is built from its catalogue,
                    so a half-drawn one would only offer controls that do nothing yet. */}
                {typeof hostState === "object" ? (
                    <div className="planner-status err">
                        the pathfinder failed to start: {hostState.failed}
                    </div>
                ) : hostState === "loading" || !inputs ? (
                    <div className="planner-loading">
                        <span className="planner-spinner"/>
                        <span>{hostState === "loading" ? "Initializing pathfinder…" : "Loading…"}</span>
                        {hostState === "loading" && props.hostProgress && (
                            <span className="planner-loading-stage">{props.hostProgress}…</span>
                        )}
                    </div>
                ) : (<>
                {/* A one-time COPY, not a mode: picking an account fills the editor with its
                    levels, pack, bank and quests and springs back to "plan as", so everything
                    below stays editable. */}
                <select className="planner-copy" value=""
                        onChange={(e) => {
                            if (e.target.value) props.onCopyFrom(e.target.value);
                            e.target.value = "";
                        }}>
                    <option value="">plan as…</option>
                    <option value="fresh">a fresh account</option>
                    <option value="maxed">a maxed account</option>
                    {copySources.length > 0 && (
                        <optgroup label="copy from an account">
                            {copySources.map((s) => (
                                <option key={s.value} value={s.value}>{s.label}</option>
                            ))}
                        </optgroup>
                    )}
                </select>

                {/* The endpoints as the map draws them: same green start, same red end, and the one
                    the next click lands on is marked — the panel and the map agree at a glance. */}
                <div className="planner-ends">
                    <Endpoint which="start" tile={start}
                              armed={props.pickTarget === "start"
                                  || (picking && !props.pickTarget && !start)}
                              onArm={() => props.onArmEndpoint("start")}
                              onCommit={(t) => props.onSetEndpoint("start", t)}/>
                    <Endpoint which="end" tile={end}
                              armed={props.pickTarget === "end"
                                  || (picking && !props.pickTarget && !!start && !end)}
                              onArm={() => props.onArmEndpoint("end")}
                              onCommit={(t) => props.onSetEndpoint("end", t)}/>
                    <div className="planner-ends-actions">
                        {props.onFollowChange && (
                            <label className="planner-follow"
                                   title="keep the camera on the bot walking the plan; panning lets go">
                                <input type="checkbox" checked={props.follow ?? false}
                                       onChange={(e) => props.onFollowChange?.(e.target.checked)}/>
                                follow
                            </label>
                        )}
                        {/* One button, because there is only one thing to ask for: drop both ends
                            and start picking again. It lights while a pick is armed. */}
                        <button type="button"
                                className={`planner-act-pick${picking ? " active" : ""}`}
                                onClick={props.onClearRoute}>pick
                        </button>
                        {/* The same plan again: the first answer pays for whatever the engine had
                            not built yet, the repeats show what a warm engine costs. */}
                        <button type="button" className="planner-act-replan"
                                disabled={!start || !end || props.loading}
                                title="plan the same route again"
                                onClick={props.onReplan}>replan
                        </button>
                        {/* Every walking component this account can get to from the start, on any
                            floor: the components layer shows those and hides the rest. */}
                        {props.onReachable && (
                            <button type="button"
                                    className={`planner-act-reachable${reachOn ? " active" : ""}`}
                                    disabled={!start}
                                    title={reach.error
                                        ?? "show only the walking components this account can reach from the start"}
                                    onClick={() => setReachOn((v) => !v)}>
                                reachable{reachOn && reach.info && !reach.loading
                                    ? ` ${reach.info.count}/${reach.info.total}`
                                    : reachOn && reach.loading ? " …" : ""}
                            </button>
                        )}
                    </div>
                </div>

                {/* ---- the answer, first: it is what the panel is for ---- */}
                <Result host={props.host} plan={plan} loading={props.loading} error={props.error} inputs={inputs}
                        nameOf={nameOf} onHoverStep={props.onHoverStep}
                        onFocusStep={props.onFocusStep}
                        accountRequest={start && end ? toPlanRequest(state, inputs, start, end) : null}/>

                {/* ---- levels ---- */}
                <details className="planner-section" open>
                    <summary>levels</summary>
                    <div className="planner-row">
                        <span>combat</span>
                        {/* The scale stays the whole 3-123. Below the floor the gated skills
                            already impose, the track is dim and the thumb will not go: a level
                            this account cannot have is shown as unavailable, not hidden. */}
                        <LevelSlider min={3} max={123} live={[combatFloor, 123]}
                                     value={Math.max(state.combatLevel, combatFloor)}
                                     onChange={(v) => set({
                                         combatLevel: Math.max(combatFloor, v),
                                     })}/>
                        {/* The readout is the quick jump: to the top, or from it back to the floor. */}
                        <button type="button" className="planner-val"
                                title={state.combatLevel < 123 ? "set to 123" : `set to ${combatFloor}`}
                                onClick={() => set({
                                    combatLevel: state.combatLevel < 123 ? 123 : combatFloor,
                                })}>
                            {Math.max(state.combatLevel, combatFloor)}
                        </button>
                        <Info title="combat level"
                              lines={["no gate reads it directly — it picks the danger rung, so it "
                              + "decides which aggressive NPCs the route steers around",
                                  `its floor (${combatFloor}) follows from the levels below`]}/>
                    </div>
                    {gateSkills.map((s) => {
                        const stops = sliderStops(s.breakpoints);
                        const level = state.levels[s.skill] ?? SKILL_MIN;
                        // The level is kept as set; what the gates READ is the threshold it has
                        // reached, so the ⓘ says which one and what the next would open.
                        const at = snapDown(level, stops);
                        const next = nextStop(level, stops);
                        const gain = next == null ? null
                            : s.breakpoints.find((b) => b.at === next);
                        // One line per skill: name, slider, level, ⓘ. What the next threshold opens
                        // lives in the ⓘ rather than a line of its own — it is worth a look, not
                        // a third of the panel.
                        return (
                            <div key={s.skill} className="planner-row">
                                <span>{skillLabel(s.skill)}</span>
                                <LevelSlider min={SKILL_MIN} max={SKILL_MAX} value={level}
                                             stops={stops}
                                             live={[s.breakpoints[0].at,
                                                 s.breakpoints[s.breakpoints.length - 1].at]}
                                             onChange={(v) => set({
                                                 levels: {
                                                     ...state.levels,
                                                     [s.skill]: snapNearest(v, stops),
                                                 },
                                             })}/>
                                <button type="button" className="planner-val"
                                        title={level < SKILL_MAX
                                            ? `set to ${SKILL_MAX}` : `set to ${SKILL_MIN}`}
                                        onClick={() => set({
                                            levels: {
                                                ...state.levels,
                                                [s.skill]: level < SKILL_MAX ? SKILL_MAX : SKILL_MIN,
                                            },
                                        })}>{level}</button>
                                {/* The heading carries the numbers; the list carries the names.
                                    Saying "50 opens 2:" under a heading that already reads
                                    "50 → +2 transports" is the same fact twice. */}
                                <Info title={gain ? usableLabel(gain.transports)
                                    : "all transports usable"}>
                                    {gain && <OpeningList list={gain.opens} total={gain.transports}
                                                          onFocus={props.onFocusStep}/>}
                                    {at !== level && (
                                        <div className="planner-tip-note">counts as {at}</div>
                                    )}
                                </Info>
                            </div>
                        );
                    })}
                </details>

                {/* ---- items: pack, bank, and what to arrive holding ---- */}
                <details className="planner-section" open>
                    <summary>items</summary>
                    <div className="planner-item-head">
                        <span>item</span><span title="carried now">pack</span>
                        <span title="owned, but banked">bank</span>
                        <span title="arrive holding this many">arrive</span>
                        <span title="arrive WEARING it, not merely holding it">wear</span>
                    </div>
                    {state.rows.map((row) => {
                        const key = rowKey(row);
                        const label = row.kind === "group"
                            ? familyLabel(row.label) : nameOf(row.id);
                        const standing = isStandingRow(row, inputs);
                        const info = rowInfo(row, inputs, label, props.onFocusStep);
                        return (
                            <div key={key}
                                 className={`planner-item-row${
                                     blocked.has(key) ? " planner-item-blocked" : ""}`}>
                                <span className="probe-item-name">
                                    {label}{" "}
                                    {info && <Info title={info.title}>{info.body}</Info>}
                                    {/* The standing rows stay: they are the kit every route asks
                                        about, and a panel you can dismantle is one you have to
                                        rebuild. Rows you added are yours to drop — and dropping
                                        sits beside the name rather than in a trailing column, so
                                        the amounts end where every other control does. */}
                                    {!standing && (
                                        <button type="button" className="planner-drop"
                                                title="remove row"
                                                onClick={() => set({
                                                    rows: state.rows.filter(
                                                        (r) => rowKey(r) !== key),
                                                })}>×
                                        </button>
                                    )}
                                </span>
                                <Amount value={state.inventory[key] ?? 0}
                                        onChange={(n) => set({
                                            inventory: {...state.inventory, [key]: n},
                                        })}/>
                                <Amount value={state.bank[key] ?? 0}
                                        onChange={(n) => set({bank: {...state.bank, [key]: n}})}/>
                                <Amount value={state.arrive[key] ?? 0}
                                        onChange={(n) => set({arrive: {...state.arrive, [key]: n}})}/>
                                <input type="checkbox" className="planner-equip"
                                       title={wearable(row, inputs, props.wearableItems)
                                           ? "arrive wearing it"
                                           : "this item cannot be worn"}
                                       disabled={!wearable(row, inputs, props.wearableItems)}
                                       checked={state.equip?.[key] === true}
                                       onChange={(e) => set({
                                           equip: {...state.equip, [key]: e.target.checked},
                                       })}/>
                            </div>
                        );
                    })}
                    <ItemSearch inputs={inputs} itemDefs={itemDefs} search={search}
                                onSearch={setSearch}
                                onAdd={(row) => {
                                    const key = rowKey(row);
                                    if (state.rows.some((r) => rowKey(r) === key)) return;
                                    // A row is added to be carried: one in the pack, one on
                                    // arrival. A row at 0/0/0 asks the planner nothing, and every
                                    // add used to be followed by the same two clicks.
                                    set({
                                        rows: [...state.rows, row],
                                        inventory: {...state.inventory, [key]: 1},
                                        arrive: {...state.arrive, [key]: 1},
                                    });
                                    setSearch("");
                                }}/>
                </details>

                {/* Every quest some gate reads, in the game's own journal order (the server sorts
                    them by quest id). Each offers only the stages that change an answer. */}
                <details className="planner-section">
                    <summary>
                        quests ({Object.values(state.quests).filter((s) => s !== 0).length} set)
                    </summary>
                    {(inputs?.quests ?? []).map((q) => {
                        // Spaced by stage VALUE: a quest gated at 1 and 10 puts those notches
                        // where they actually fall, like the skill sliders, rather than evenly.
                        // "Done" is −1 on the wire — the END of the quest, not something below its
                        // start — so it takes the position one past the highest declared stage,
                        // which keeps the axis monotonic without inventing a stage number.
                        const stages = questStages(q);
                        const numbered = stages.filter((s) => s !== -1);
                        const donePos = (numbered.length ? Math.max(...numbered) : 0) + 1;
                        const positions = [...numbered, donePos];
                        const stage = state.quests[q.id] ?? 0;
                        return (
                            <div key={q.id} className="planner-quest">
                                <span>
                                    {q.name}{" "}
                                    {/* What each stage opens, as the skill rows list their levels. */}
                                    <Info title={`${q.name} · ${q.transports} transports`}>
                                        {q.atLeast.map((t) => (
                                            <OpeningList key={`ge${t.at}`} list={t.opens}
                                                         total={t.transports}
                                                         prefix={`stage ≥ ${t.at} · `}
                                                         onFocus={props.onFocusStep}/>
                                        ))}
                                        {q.exact.map((t) => (
                                            <OpeningList key={`eq${t.at}`} list={t.opens}
                                                         total={t.transports}
                                                         prefix={`stage ${t.at} exactly · `}
                                                         onFocus={props.onFocusStep}/>
                                        ))}
                                        {q.done && (
                                            <OpeningList list={q.done.opens} total={q.done.transports}
                                                         prefix="done · " onFocus={props.onFocusStep}/>
                                        )}
                                    </Info>
                                </span>
                                <LevelSlider min={0} max={donePos}
                                             value={stage === -1 ? donePos : stage}
                                             stops={positions}
                                             onChange={(p) => {
                                                 // Snap to a declared stage: the levels between
                                                 // two of them change nothing a gate reads.
                                                 const at = snapNearest(p, positions);
                                                 set({
                                                     quests: {
                                                         ...state.quests,
                                                         [q.id]: at === donePos ? -1 : at,
                                                     },
                                                 });
                                             }}/>
                                {/* The readout is also the quick toggle: the two ends are what
                                    you actually reach for, and dragging to them is a waste. */}
                                <button type="button" className="planner-quest-val"
                                        title={stage === -1
                                            ? "back to not started" : "mark done"}
                                        onClick={() => set({
                                            quests: {
                                                ...state.quests,
                                                [q.id]: stage === -1 ? 0 : -1,
                                            },
                                        })}>{stageLabel(stage)}</button>
                            </div>
                        );
                    })}
                </details>

                {/* Every player-cache key some gate reads. The server never sends its cache, so a
                    key starts UNKNOWN and its gates let the route through; saying what the
                    account's value is makes them test it. */}
                <details className="planner-section">
                    <summary>
                        player cache ({Object.keys(state.cache).length} known)
                    </summary>
                    <div className="planner-tip-note">unknown values let their gates through</div>
                    {(inputs?.cache ?? []).map((entry) => (
                        <CacheRow key={entry.key} entry={entry} value={state.cache[entry.key]}
                                  onFocus={props.onFocusStep}
                                  onChange={(v) => {
                                      const cache = {...state.cache};
                                      if (v === undefined) delete cache[entry.key];
                                      else cache[entry.key] = v;
                                      set({cache});
                                  }}/>
                    ))}
                </details>

                {/* ---- routing choices ---- */}
                <details className="planner-section" open>
                    <summary>routing</summary>
                    <div className="planner-checks">
                        {(inputs?.policy ?? []).map((flag) => {
                            const knob = POLICY_FLAGS[flag.key];
                            if (!knob) return null; // a knob this panel has no checkbox for
                            const policy = policyOf(state.policy);
                            return (
                                <label key={flag.key} className="planner-check">
                                    <input type="checkbox" checked={knob.get(policy)}
                                           onChange={(e) => set({
                                               policy: knob.set(policy, e.target.checked),
                                           })}/>
                                    {/* The catalogue's own wording. This used to mangle the KEY
                                        into a label and ignore the published one entirely. */}
                                    {flag.label}
                                </label>
                            );
                        })}
                    </div>
                </details>
                </>)}
            </div>
        </aside>
    );
}

const BOOL_STATES: { label: string; value: boolean | undefined }[] = [
    {label: "unknown", value: undefined},
    {label: "set", value: true},
    {label: "unset", value: false},
];

/**
 * One player-cache key: unknown, or the value the account has. A flag picks between the three; a
 * counter is unknown until a number is typed, and "unknown" clears it again. Both lead with the
 * same "unknown" segment, so the column reads down. The ⓘ lists what each value its gates ask for
 * opens.
 */
function CacheRow({entry, value, onChange, onFocus}: {
    entry: PlannerCacheKey;
    value: boolean | number | undefined;
    onChange: (value: boolean | number | undefined) => void;
    onFocus: (tile: { x: number; z: number }) => void;
}) {
    const int = entry.kind === "int";
    const label = (at: number) => int ? `≥ ${at} · ` : at === 1 ? "set · " : "unset · ";
    return (
        <div className="planner-cache">
            <span>{entry.key}</span>
            {int ? (
                <span className="planner-seg">
                    <button type="button" className={value === undefined ? "active" : ""}
                            onClick={() => onChange(undefined)}>unknown</button>
                    <input type="number" min={0} placeholder="value"
                           value={value === undefined ? "" : Number(value)}
                           onChange={(e) => onChange(e.target.value === ""
                               ? undefined : Math.max(0, parseInt(e.target.value, 10) || 0))}/>
                </span>
            ) : (
                <span className="planner-seg">
                    {BOOL_STATES.map((s) => (
                        <button key={s.label} type="button"
                                className={value === s.value ? "active" : ""}
                                onClick={() => onChange(s.value)}>{s.label}</button>
                    ))}
                </span>
            )}
            <Info title={`${entry.key} · ${entry.transports} transports`}>
                {entry.targets.map((t) => (
                    <OpeningList key={t.at} list={t.opens} total={t.transports}
                                 prefix={label(t.at)} onFocus={onFocus}/>
                ))}
            </Info>
        </div>
    );
}

/** "120, 648" / "120 648" — whatever a tile readout elsewhere in the app can be copied as. */
function parseTile(text: string): { x: number; z: number } | null {
    const m = text.match(/(-?\d+)\s*[,\s]\s*(-?\d+)/);
    return m ? {x: Number(m[1]), z: Number(m[2])} : null;
}

/**
 * One endpoint: the map's own colour, and the coordinate as a FIELD. Focusing it arms that endpoint
 * for the next map click — so "click the box, click the map" re-picks exactly the one you meant,
 * whether or not the other is set — and typing a pair commits on Enter. Escape or leaving the field
 * abandons a half-typed pair rather than planning from it.
 */
function Endpoint(props: {
    which: "start" | "end";
    tile: { x: number; z: number } | null;
    armed: boolean;
    onArm: () => void;
    onCommit: (tile: { x: number; z: number }) => void;
}) {
    const [editing, setEditing] = useState(false);
    const [draft, setDraft] = useState("");
    const text = props.tile ? `${props.tile.x}, ${props.tile.z}` : "";
    // A coordinate READS as a coordinate until you go to change one: the row is plain text under a
    // pointer, and a click both arms this endpoint for the next map click and opens it for typing.
    const begin = () => {
        setDraft(text);
        setEditing(true);
        props.onArm();
    };
    return (
        <div className={`planner-end${props.armed ? " planner-end-armed" : ""}`} onClick={begin}>
            <span className={`path-label path-label-${props.which}`}>{props.which}</span>
            {editing ? (
                <input className="planner-end-tile" type="text" autoFocus value={draft}
                       // Opened to be replaced: the whole coordinate is selected.
                       onFocus={(e) => e.target.select()}
                       onChange={(e) => setDraft(e.target.value)}
                       onKeyDown={(e) => {
                           if (e.key === "Enter") {
                               const tile = parseTile(draft);
                               if (tile) props.onCommit(tile);
                               setEditing(false);
                           } else if (e.key === "Escape") {
                               setEditing(false);
                           }
                       }}
                       onBlur={() => setEditing(false)}/>
            ) : (
                <span className="planner-end-tile">
                    {text || (props.armed ? "click the map" : "—")}
                </span>
            )}
        </div>
    );
}

/**
 * What a row's ⓘ says: which gates read this item, and at what counts. A family lists the tiers it
 * accepts; an item lists the counts some gate asks for and, where one exists, the count a gate
 * refuses ABOVE. An item no gate reads has nothing to say and gets no ⓘ.
 */
function rowInfo(row: PlannerRow, inputs: PlannerInputs | null, label: string,
                 onFocus: (tile: { x: number; z: number }) => void,
): { title: string; body: ReactNode } | null {
    if (row.kind === "group") {
        const group = inputs?.itemGroups.find((g) => g.label === row.label);
        if (!group) return null;
        return {
            title: `${label} · ${group.transports} transports`,
            body: <ul><li>any of: {group.items.map((m) => m.name).join(", ")}</li></ul>,
        };
    }
    const item = inputs?.items.find((i) => i.id === row.id);
    if (!item) return null;
    // A count of one says nothing a row about carrying this item does not: "1+ · Jungle" on the
    // machete row. Only a real count is worth stating, and it is a count, not "or more" — a gate
    // asking for 10 coins is satisfied by 10.
    return {
        title: `${label} · ${item.transports} transports`,
        body: (
            <>
                {item.carry.map((t) => (
                    <OpeningList key={`c${t.at}`} list={t.opens} total={t.transports}
                                 prefix={t.at > 1 ? `${t.at} · ` : ""} onFocus={onFocus}/>
                ))}
                {item.mustNotCarry.map((t) => (
                    <OpeningList key={`n${t.at}`} list={t.opens} total={t.transports}
                                 prefix={`over ${t.at} closes · `} onFocus={onFocus}/>
                ))}
            </>
        ),
    };
}

/** "+1 transport usable", "+3 transports usable". */
function usableLabel(n: number): string {
    return `+${n} transport${n === 1 ? "" : "s"} usable`;
}

/**
 * Transports by name, each a link to its place on the map when it has one. {@code total} is the
 * true count when {@code list} is only a sample, so the rest is at least acknowledged.
 */
function OpeningList({list, total, prefix = "", onFocus}: {
    list: PlannerOpening[];
    total?: number;
    prefix?: string;
    onFocus: (tile: { x: number; z: number }) => void;
}) {
    const more = (total ?? list.length) - list.length;
    return (
        <ul className="planner-openings">
            {list.map((o, i) => (
                <li key={i}>
                    {prefix}
                    {o.x != null && o.z != null ? (
                        <button type="button" className="planner-link"
                                title={`show ${o.x}, ${o.z} on the map`}
                                onClick={() => onFocus({x: o.x!, z: o.z!})}>{o.name}</button>
                    ) : o.name}
                </li>
            ))}
            {more > 0 && <li className="planner-tip-note">…and {more} more</li>}
        </ul>
    );
}

/**
 * The account as the engine sees it, fetched when this opens: the facts its gates read and the
 * rules they make, each with this account's answer, and what it may use. Each list folds away —
 * three hundred facts are for looking something up, not for reading top to bottom.
 */
function AccountBreakdown({host, request, onFocus}: {
    host: PlannerHost;
    request: PlanRequest;
    onFocus: (tile: { x: number; z: number }) => void;
}) {
    const [data, setData] = useState<PlannerAccount | null>(null);
    const [error, setError] = useState<string | null>(null);
    useEffect(() => {
        let alive = true;
        host.account(request)
            .then((d) => alive && setData(d))
            .catch((e) => alive && setError(e.message ?? String(e)));
        return () => {
            alive = false;
        };
        // One fetch per opening: the tooltip mounts this afresh each time it opens.
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);
    if (error) return <div className="planner-result err">{error}</div>;
    if (!data) return <div className="planner-pack-empty">reading the account…</div>;
    const holding = data.facts.filter((f) => f.holds).length;
    const passing = data.rules.filter((r) => r.passes).length;
    return (
        <div className="planner-breakdown">
            <details>
                <summary>{data.usable.length} of {data.total} transports usable</summary>
                <OpeningList list={data.usable} onFocus={onFocus}/>
            </details>
            <details>
                <summary>{data.facts.length} facts · {holding} hold</summary>
                <ul>
                    {data.facts.map((f, i) => (
                        <li key={i} className={f.holds ? "ok" : "no"}>
                            {f.holds ? "✓" : "✗"} {f.fact} <em>· {f.transports}</em>
                        </li>
                    ))}
                </ul>
            </details>
            <details>
                <summary>{data.rules.length} gate rules · {passing} pass</summary>
                <ul>
                    {data.rules.map((r, i) => (
                        <li key={i} className={r.passes ? "ok" : "no"}>
                            {r.passes ? "✓" : "✗"} {r.rule} <em>· {r.transports}</em>
                        </li>
                    ))}
                </ul>
            </details>
            {data.cacheAssumed.length > 0 && (
                <details>
                    <summary>{data.cacheAssumed.length} player-cache values assumed passable</summary>
                    <ul>{data.cacheAssumed.map((k) => <li key={k}>{k}</li>)}</ul>
                </details>
            )}
        </div>
    );
}

/**
 * A level slider, on Base UI's headless Slider: real thumb and track elements, with the keyboard,
 * touch and pointer behaviour that a native range input only half provides once it is restyled.
 *
 * <p>Two things it deliberately does NOT provide, because no library does: ticks at ARBITRARY
 * positions, and snapping to IRREGULAR stops ({@code step} is a fixed interval, and agility's
 * thresholds are 5, 10, 15, 18, 20, 25, 30, 32, 35, 40, 49, 50, 52, 57, 67). So the ticks are real
 * elements positioned per threshold, and the caller snaps in {@code onChange}. The stretch below the
 * lowest threshold and above the highest is dimmed: nothing a gate asks can change there.
 */
function LevelSlider(props: {
    min: number;
    max: number;
    value: number;
    /** Where it may land, and where a tick is drawn — thresholds, plus 1 and 99. */
    stops?: number[];
    /** The stretch that decides something: the lowest and highest GATE threshold. */
    live?: [number, number];
    onChange: (value: number) => void;
}) {
    const {min, max, stops = []} = props;
    const pct = (level: number) => ((level - min) / (max - min)) * 100;
    const live = props.live
        ? {left: `${pct(props.live[0])}%`, right: `${100 - pct(props.live[1])}%`}
        : null;
    return (
        <Slider.Root className="planner-slider" min={min} max={max} value={props.value}
                     onValueChange={(v) => props.onChange(typeof v === "number" ? v : v[0])}>
            <Slider.Control className="planner-slider-control">
                <Slider.Track className="planner-slider-track">
                    {live && <span className="planner-slider-live" style={live}/>}
                    {stops.map((s) => (
                        <span key={s} className="planner-slider-tick" style={{left: `${pct(s)}%`}}/>
                    ))}
                    <Slider.Indicator className="planner-slider-indicator"/>
                    <Slider.Thumb className="planner-slider-thumb"/>
                </Slider.Track>
            </Slider.Control>
        </Slider.Root>
    );
}

/** A small number field — the editor's amounts are all "how many". */
function Amount(props: { value: number; disabled?: boolean; onChange: (n: number) => void }) {
    return (
        <input type="number" min={0} value={props.value} disabled={props.disabled}
               onChange={(e) => props.onChange(Math.max(0, parseInt(e.target.value, 10) || 0))}/>
    );
}

/** Module-level so `useFloating` doesn't re-run its deep middleware compare per hover. */
const TIP_MIDDLEWARE = [offset(6), flip({padding: 8}), shift({padding: 8})];

/**
 * An ⓘ whose list FLOATS over the panel rather than expanding in place: these lists run to a dozen
 * transport names, and a row that grows by that much shoves whatever you were reading off screen.
 * Hover or keyboard focus opens it; `flip`/`shift` keep it on screen at the panel's edges.
 */
/** The one ⓘ that is open, by its closer: opening another closes it. */
let closeOpenInfo: (() => void) | null = null;

function Info(props: { title?: string; lines?: string[]; children?: ReactNode; wide?: boolean }) {
    const [open, setOpen] = useState(false);
    const close = useRef(() => setOpen(false)).current;
    const onOpenChange = (next: boolean) => {
        if (next) {
            if (closeOpenInfo && closeOpenInfo !== close) closeOpenInfo();
            closeOpenInfo = close;
        } else if (closeOpenInfo === close) {
            closeOpenInfo = null;
        }
        setOpen(next);
    };
    const {refs, floatingStyles, context} = useFloating({
        open,
        onOpenChange,
        // Leftward: the panel floats over the map's right side, so a tooltip opening left stays on
        // the panel it belongs to instead of covering the route it is describing. flip() still
        // rescues it if the panel has been dragged flush to the left edge.
        placement: "left",
        middleware: TIP_MIDDLEWARE,
        whileElementsMounted: autoUpdate,
    });
    // safePolygon keeps it open while the pointer crosses the gap to the tooltip, so a list that
    // scrolls can be moused into and copied out of. That is the whole job — deliberately no click
    // to pin, which only latched the tooltip open with nothing but a stray click to shut it.
    const {getReferenceProps, getFloatingProps} = useInteractions([
        useHover(context, {move: false, handleClose: safePolygon({blockPointerEvents: false})}),
        useFocus(context),
        useDismiss(context),
        useRole(context, {role: "tooltip"}),
    ]);
    if (!props.children && !props.lines?.length && !props.title) return null;
    return (
        <>
            <button type="button" className="planner-info" ref={refs.setReference}
                    {...getReferenceProps()}>ⓘ
            </button>
            {open && (
                <FloatingPortal>
                    {/* Focusable: a click inside (selecting text, opening a list) moves focus
                        INTO the tip, which the focus interaction reads as staying — without it the
                        focus left the ⓘ for nowhere, and that closed the tip under the click. */}
                    <div ref={refs.setFloating} style={floatingStyles} tabIndex={-1}
                         className={`planner-tip${props.wide ? " wide" : ""}`}
                         {...getFloatingProps()}>
                        {/* Optional: a tooltip whose content speaks for itself (the pack grid)
                            does not need a heading restating what was moused over. */}
                        {props.title && <div className="planner-tip-title">{props.title}</div>}
                        {props.children ?? (
                            <ul>
                                {props.lines?.map((l, i) => <li key={i}>{l}</li>)}
                            </ul>
                        )}
                    </div>
                </FloatingPortal>
            )}
        </>
    );
}

/** One search hit: the row it would add, and how the list describes it. */
interface ItemMatch {
    row: PlannerRow;
    label: string;
    note: string;
}

/**
 * Add a row. Gate families and gate items rank first — they are what changes a route — but the search
 * covers EVERY item, because a loadout may want something no gate has ever asked for (a bank full of
 * lobsters is the whole point of the banker demo).
 *
 * <p>The field is Base UI's Autocomplete: arrow keys walk the list, Enter adds the highlighted hit,
 * Escape closes. The ranking above is the whole filter — the component is told so with
 * {@code filter={null}} — because a collator's "contains" would re-order families below the items
 * they stand for.
 */
function ItemSearch(props: {
    inputs: PlannerInputs | null;
    itemDefs: ItemNames | null;
    search: string;
    onSearch: (s: string) => void;
    onAdd: (row: PlannerRow) => void;
}) {
    const {inputs, itemDefs, search} = props;
    const matches = useMemo(() => {
        const q = search.trim().toLowerCase();
        if (q === "") return [];
        const out: ItemMatch[] = [];
        // A family's tiers are NOT offered separately: searching "pickaxe" offering both "a pickaxe"
        // and a bronze pickaxe marked "no gate reads it" is a contradiction from where the user
        // sits — the gate reads the family, and the family is the row that satisfies it.
        const inAFamily = new Set<number>();
        for (const g of inputs?.itemGroups ?? []) {
            for (const i of g.items) inAFamily.add(i.id);
            if (g.label.toLowerCase().includes(q)
                || g.items.some((i) => i.name.toLowerCase().includes(q))) {
                out.push({
                    row: {kind: "group", label: g.label},
                    label: familyLabel(g.label),
                    note: `any of ${g.items.length} · ${g.transports} transports`,
                });
            }
        }
        for (const i of inputs?.items ?? []) {
            if (inAFamily.has(i.id)) continue;
            if (i.name.toLowerCase().includes(q) || String(i.id) === q) {
                out.push({
                    row: {kind: "item", id: i.id},
                    label: i.name,
                    note: `${i.transports} transports`,
                });
            }
        }
        const gateIds = new Set((inputs?.items ?? []).map((i) => i.id));
        for (const [id, name] of Object.entries(itemDefs ?? {})) {
            if (out.length >= 12) break;
            const numeric = Number(id);
            if (gateIds.has(numeric) || inAFamily.has(numeric)) continue;
            if (name.toLowerCase().includes(q) || id === q) {
                out.push({row: {kind: "item", id: numeric}, label: name, note: "for a loadout"});
            }
        }
        return out.slice(0, 12);
    }, [inputs, itemDefs, search]);

    // The matches float over the panel, as a dropdown does, rather than growing it: a list that
    // pushes the rows below it away moves whatever you were about to click.
    return (
        <div className="planner-search">
            <Autocomplete.Root
                items={matches}
                filter={null}
                value={search}
                // A pick fills the field with the hit's label (reason "item-press"); the field is
                // ours, and an add clears it, so that one write is not taken.
                onValueChange={(v, details) => {
                    if (details.reason !== "item-press") props.onSearch(v);
                }}
                // Escape empties the field as well as closing the list, as it always did here.
                onOpenChange={(open, details) => {
                    if (!open && details.reason === "escape-key") props.onSearch("");
                }}
                autoHighlight
                itemToStringValue={(m) => m.label}>
                <Autocomplete.Input type="search" placeholder="+ add an item…"/>
                <Autocomplete.Portal>
                    <Autocomplete.Positioner className="planner-matches-positioner"
                                             sideOffset={2} collisionPadding={8}>
                        <Autocomplete.Popup className="planner-matches">
                            <Autocomplete.Empty className="planner-matches-empty">
                                no such item
                            </Autocomplete.Empty>
                            <Autocomplete.List>
                                {(m: ItemMatch) => (
                                    <Autocomplete.Item key={rowKey(m.row)} value={m}
                                                       className="planner-match"
                                                       onClick={() => props.onAdd(m.row)}>
                                        {m.label} <em>{m.note}</em>
                                    </Autocomplete.Item>
                                )}
                            </Autocomplete.List>
                        </Autocomplete.Popup>
                    </Autocomplete.Positioner>
                </Autocomplete.Portal>
            </Autocomplete.Root>
        </div>
    );
}

/** The plan: what it costs, what the account came out as, and every step with its diff. */
function Result(props: {
    host: PlannerHost;
    plan: PlanResponse | null;
    loading: boolean;
    error: string | null;
    inputs: PlannerInputs | null;
    nameOf: (id: number) => string;
    onHoverStep: (tile: { x: number; z: number } | null) => void;
    /** Put a step's own tile in the middle of the map — whichever map is up. */
    onFocusStep: (tile: { x: number; z: number }) => void;
    /** The account this plan was asked for, for the breakdown panel; null without endpoints. */
    accountRequest: PlanRequest | null;
}) {
    const {plan, nameOf} = props;
    // A plan in hand STAYS on screen while the next one computes, dimmed. Swapping it for the word
    // "planning" collapsed the panel to one line and shoved every control below it up and back on
    // each keystroke — the answer changing size is fine, the answer vanishing is not.
    if (props.error) return <div className="planner-result err">error: {props.error}</div>;
    if (!plan) {
        return (
            <div className="planner-result">
                {props.loading ? "planning…" : "pick a start and an end tile"}
            </div>
        );
    }
    if (!plan.found) {
        // "the loadout forbids all of them" is true and useless: it names the CATEGORY, and the
        // reader is left to guess which of their rows it meant. So the verdict leads with the
        // blockers — each proven by a re-plan with that one thing lifted — and every one carries
        // the edit that removes it. The rows those blockers name light up in the table below.
        const why = plan.why;
        return (
            <div className="planner-result err">
                <div className="planner-norecap">
                    no route — {why?.summary ?? plan.diagnosis}
                    {why && <span className="planner-norecap-kind">{why.kind.toLowerCase()}</span>}
                </div>
                {why && why.blockers.length > 0 && (
                    <ul className="planner-blockers">
                        {why.blockers.map((b, i) => (
                            <li key={i}>
                                <div className="planner-blocker-what">{b.what}</div>
                                <div className="planner-blocker-why">
                                    {b.why}
                                    {b.transport && <> — <code>{b.transport}</code></>}
                                </div>
                                <div className="planner-blocker-fix">{b.fix}</div>
                            </li>
                        ))}
                    </ul>
                )}
                {why && why.blockers.length === 0 && why.hops.length > 0 && (
                    <div className="planner-blocker-hops">
                        the route it tried: {why.hops.join(" → ")}
                    </div>
                )}
                <Timings timings={plan.timings} loading={props.loading}/>
            </div>
        );
    }
    const rows = collapseWalks(plan.steps);
    return (
        <div className={`planner-result${props.loading ? " planner-busy" : ""}`}>
            <div className="planner-cost">
                <strong>{plan.ticks} ticks</strong>
                <span>{plan.account?.usableTransports} of {plan.account?.totalTransports} transports{" "}
                    {props.accountRequest && (
                        <Info wide>
                            <AccountBreakdown host={props.host} request={props.accountRequest}
                                              onFocus={props.onFocusStep}/>
                        </Info>
                    )}
                </span>
            </div>
            <ol className="planner-steps">
                {rows.map((row, i) => (
                    <li key={i} className={`planner-step planner-step-${row.step.type}`}
                        onMouseEnter={() => props.onHoverStep({x: row.step.x, z: row.step.z})}
                        onMouseLeave={() => props.onHoverStep(null)}
                        onClick={() => props.onFocusStep({x: row.step.x, z: row.step.z})}
                        title={`show (${row.step.x}, ${row.step.z}) on the map`}>
                        {row.step.type === "walk" && (
                            <span>walk ×{row.walks} → ({row.step.x}, {row.step.z})</span>
                        )}
                        {row.step.type === "hop" && (
                            <span>
                                {row.step.name} <em>{row.step.cost ?? 0}</em>
                                {row.step.wears.length > 0 && (
                                    <div className="planner-wears">
                                        wears: {row.step.wears.map(nameOf).join(", ")}
                                    </div>
                                )}
                                {row.step.req && <div className="hop-req">{row.step.req}</div>}
                                {/* The fare, stated like a stop's manifest: a toll that takes
                                    10 coins should say so where the stop that fetched them does. */}
                                <PackDiff changes={row.delta} nameOf={nameOf}/>
                            </span>
                        )}
                        {row.step.type === "bank" && (
                            <span>
                                bank stop ({row.step.x}, {row.step.z})
                                {row.step.because.length > 0 && (
                                    <em> for {row.step.because.join(", ")}</em>
                                )}
                                <PackDiff changes={row.delta} nameOf={nameOf}/>
                            </span>
                        )}
                        {/* Not a jump link: stop the click here, so reading the pack does not
                            also fling the map across the world. */}
                        <span className="planner-step-pack"
                              onClick={(e) => e.stopPropagation()}>
                            <Info>
                                <PackGrid pack={row.step.pack} nameOf={nameOf}/>
                            </Info>
                        </span>
                    </li>
                ))}
            </ol>
            <Timings timings={plan.timings} loading={props.loading}/>
        </div>
    );
}

/**
 * What the bot's plan had to build first, in words. A plan is fast when the engine has already
 * seen this kind of trip and slow the first time, and "N metrics built" said neither which kind nor
 * why.
 */
function builtLine(t: PlanTimings): string {
    const built: string[] = [];
    if (t.botWeightSetsBuilt > 0) {
        built.push(`${t.botWeightSetsBuilt} routing-weight set(s) · first plan for an account with`
            + " these usable transports and this danger level")
    }
    if (t.botLegPlanesBuilt > 0) {
        built.push(`${t.botLegPlanesBuilt} distance table(s) · first plan through that part of the map`);
    }
    return built.length === 0
        ? "…answered entirely from what earlier plans built"
        : "…had to build " + built.join("; ");
}

/**
 * What this answer cost beyond the two calls a bot makes — the walk simulation, the read-outs and
 * any diagnosis. The request's total includes the bot's estimate and plan, so they come off it.
 */
function diagMs(t: PlanTimings): number {
    return Math.round((t.totalMs - t.estimateMs - t.botPlanMs) * 100) / 100;
}

/**
 * The answer's cost, split the way it matters: what a live BOT would pay for this trip, and what
 * drawing it here adds. The planner simulates the walk a tick at a time with a fresh plan every
 * tick, so a long route is mostly that — not a sign that planning it is slow for a bot.
 */
function Timings({timings: t, loading}: { timings: PlanTimings; loading: boolean }) {
    const lines = [
        `a bot's estimate: ${t.estimateMs} ms`,
        `a bot's first plan: ${t.botPlanMs} ms`,
        builtLine(t),
        `drawing the walk: ${t.simulatedTicks} ticks · ${t.simulatedPlans} plans`
        + ` + ${t.simulatedWalks} walks in ${t.simulationPlanMs} ms · `
        + `${t.simulationWalkMs} ms tile search`,
        `counting usable transports: ${t.derivedMs} ms`,
    ];
    if (t.diagnosisMs > 0) {
        lines.push(`no-route diagnosis: ${t.diagnosisMs} ms`);
    }
    return (
        <div className="planner-timings">
            {loading ? "planning… · " : ""}est {t.estimateMs} ms · plan {t.botPlanMs} ms · diag{" "}
            {diagMs(t)} ms{" "}
            <Info title="where the time went" lines={lines}/>
        </div>
    );
}

/** One item's signed change across a step, plus what the pack holds once it has happened. */
interface PackChange {
    id: number;
    delta: number;
    after: number;
}

/** Total per item id — a pack is slots, and one stack can sit across more than one of them. */
function packTotals(pack: PlanPackItem[] | undefined): Map<number, number> {
    const out = new Map<number, number>();
    for (const it of pack ?? []) out.set(it.id, (out.get(it.id) ?? 0) + it.amount);
    return out;
}

/**
 * What a step changed about the pack, signed.
 *
 * <p>A stop's manifest and a hop's fare are the same fact — the pack before against the pack after
 * — so one signed diff states both the same way. Stating them differently is what made a stop read
 * "+10 Coins" while the toll that spent them said nothing at all, and a deposit read "→0 Axe",
 * which is the absolute target the engine works in rather than the change a reader wants.
 */
function packDelta(before: PlanPackItem[] | undefined,
                   after: PlanPackItem[] | undefined): PackChange[] {
    const a = packTotals(before);
    const b = packTotals(after);
    const out: PackChange[] = [];
    for (const id of new Set([...a.keys(), ...b.keys()])) {
        const delta = (b.get(id) ?? 0) - (a.get(id) ?? 0);
        if (delta !== 0) out.push({id, delta, after: b.get(id) ?? 0});
    }
    // Gains first, each largest first: a stop reads as what you came away with.
    return out.sort((x, y) => y.delta - x.delta);
}

/** A step's pack change as signed rows — the one renderer for a stop's manifest and a hop's fare. */
function PackDiff({changes, nameOf}: {
    changes: PackChange[]; nameOf: (id: number) => string;
}) {
    if (changes.length === 0) return null;
    return (
        <div className="planner-diff">
            {changes.map((c) => {
                // The running total only when it says something the change does not: a gain that
                // started from nothing, or a loss that spent everything, is already fully stated.
                const total = c.delta > 0 ? c.after !== c.delta : c.after !== 0;
                return (
                    <span key={c.id} className={c.delta > 0 ? "planner-take" : "planner-give"}>
                        {nameOf(c.id)} {c.delta > 0 ? "+" : "-"}{Math.abs(c.delta)}
                        {total ? ` → ${c.after}` : ""}
                    </span>
                );
            })}
        </div>
    );
}

/**
 * A pack as the preview draws it: one tile per item, worn and loose apart. The server gives a
 * non-stackable a slot per unit — thirty sharks are thirty slots — but thirty identical tiles say
 * nothing one tile with "30" does not. Slot numbers are the first slot each group came from.
 */
function collapsePack(pack: PlanPackItem[]): PlanPackItem[] {
    const groups = new Map<string, PlanPackItem>();
    for (const it of pack) {
        const key = `${it.id}:${it.equipped}`;
        const seen = groups.get(key);
        if (seen) {
            seen.amount += it.amount;
        } else {
            groups.set(key, {...it});
        }
    }
    return [...groups.values()];
}

/**
 * A step's pack, drawn the way the bot inspector's inventory tab draws a real one — same sprites,
 * same worn flag, since worn in RSC is a property of the slot rather than a second container.
 *
 * <p>This is the PLANNER'S projection, not a live read: what the engine believes the bot is holding
 * standing on that tile. That is the whole reason a bank stop is legible — you can see the trip
 * arrive short and leave carrying what the loadout asked for.
 */
function PackGrid({pack, nameOf}: {
    pack: PlanPackItem[] | undefined; nameOf: (id: number) => string;
}) {
    const [atlas, setAtlas] = useState<ItemAtlasIndex | null>(null);
    useEffect(() => {
        let alive = true;
        getItemAtlas().then((a) => alive && setAtlas(a));
        return () => {
            alive = false;
        };
    }, []);
    // The frontend ships on a build and the runner on a restart, so a plan from a backend that
    // predates the pack field arrives without one. Absent is not the same as empty: say so rather
    // than throwing on `.length` and blanking the panel.
    if (!pack) return <div className="planner-pack-empty">pack not reported</div>;
    if (pack.length === 0) return <div className="planner-pack-empty">empty pack</div>;
    return (
        <div className="planner-pack">
            {collapsePack(pack).map((it) => (
                <div key={it.slot}
                     className={`planner-pack-slot${it.equipped ? " worn" : ""}`}
                     title={`${nameOf(it.id)}${it.amount > 1 ? ` ×${it.amount}` : ""}`
                         + (it.equipped ? " (worn)" : "")}>
                    <ItemIcon atlas={atlas} id={it.id} box={26}/>
                    {it.amount > 1 && <span className="planner-pack-n">{it.amount}</span>}
                </div>
            ))}
        </div>
    );
}

/** Several changes to one item across merged steps, summed, keeping the count they end on. */
function mergeChanges(changes: PackChange[]): PackChange[] {
    const byId = new Map<number, PackChange>();
    for (const c of changes) {
        const prev = byId.get(c.id);
        byId.set(c.id, prev ? {id: c.id, delta: prev.delta + c.delta, after: c.after} : c);
    }
    return [...byId.values()].filter((c) => c.delta !== 0).sort((x, y) => y.delta - x.delta);
}

/** Consecutive walk tiles as one row: the interesting steps are the hops and the stops. */
function collapseWalks(
    steps: PlanStep[]): { step: PlanStep; walks: number; delta: PackChange[] }[] {
    const out: { step: PlanStep; walks: number; delta: PackChange[] }[] = [];
    steps.forEach((step, i) => {
        // The first step changed nothing — you simply start out holding what you hold.
        const delta = i === 0 ? [] : packDelta(steps[i - 1].pack, step.pack);
        const last = out[out.length - 1];
        if (step.type === "walk" && last && last.step.type === "walk") {
            last.step = step;
            last.walks += 1;
            // Walking should cost nothing; if it ever does, say so rather than swallow it.
            if (delta.length) last.delta = [...last.delta, ...delta];
        } else if (step.type === "bank" && last && last.step.type === "bank"
            && last.step.x === step.x && last.step.z === step.z) {
            // ONE visit to the counter. The engine derives a stop from one reason at a time, so a
            // trip that banks what it carries and then draws a fare settles TWICE at the same
            // booth — two rows naming the same tile, with the manifest split between them, which
            // reads as a withdrawal gone missing. Spreading the later step keeps its pack, so the
            // row's ⓘ still shows what the whole visit leaves with.
            //
            // The reported duration still counts both settles: only the engine can merge those.
            last.step = {
                ...step,
                because: [...new Set([...last.step.because, ...step.because])],
            };
            last.delta = mergeChanges([...last.delta, ...delta]);
        } else {
            out.push({step, walks: step.type === "walk" ? 1 : 0, delta});
        }
    });
    return out;
}
