import type {PlannerInputs, PlannerThreshold} from "./plannerApi";

/**
 * The editor's own arithmetic: fresh-account levels, the combat-level formula and what a chosen
 * combat level implies, threshold snapping, and the adapter that lets the map draw a plan.
 *
 * <p>Combat level is asked for as ONE number rather than seven stats, because nothing but the danger
 * rung reads attack/strength/defense/hits — so the panel synthesizes stats that hit the asked level
 * ({@link statsForCombatLevel}) and the server plans against those. Magic, prayer, ranged and
 * strength are different: their own gates read them, so they stay real inputs and the combat level's
 * FLOOR follows from them ({@link minCombatLevel}).
 */

/** A new account: everything at 1, hitpoints at 10. */
export const FRESH_LEVEL = 1;
export const FRESH_HITS = 10;

/** The seven skills the combat formula reads. */
const COMBAT = ["ATTACK", "DEFENSE", "STRENGTH", "HITS", "RANGED", "PRAYER", "MAGIC"] as const;

export type Levels = Record<string, number>;

/** Every skill the editor knows, at a fresh account's level. */
export function freshLevels(inputs: PlannerInputs | null): Levels {
    const out: Levels = {};
    const names = new Set<string>(inputs?.skills.map((s) => s.skill) ?? []);
    for (const c of COMBAT) names.add(c);
    for (const name of names) out[name] = name === "HITS" ? FRESH_HITS : FRESH_LEVEL;
    return out;
}

function lvl(levels: Levels, skill: string): number {
    const v = levels[skill];
    if (v != null) return v;
    return skill === "HITS" ? FRESH_HITS : FRESH_LEVEL;
}

/**
 * The server's own formula (`AccountFacts.combatLevel`, mirroring `Formulae.getCombatLevel`): the
 * ranged branch applies when attack+strength falls below 1.5x ranged.
 */
export function combatLevelOf(levels: Levels): number {
    const att = lvl(levels, "ATTACK");
    const str = lvl(levels, "STRENGTH");
    const def = lvl(levels, "DEFENSE");
    const hits = lvl(levels, "HITS");
    const range = lvl(levels, "RANGED");
    const pray = lvl(levels, "PRAYER");
    const magic = lvl(levels, "MAGIC");
    if (att + def + str + hits === 0) return 0;
    const attack = att + str;
    const defense = def + hits;
    const mage = (pray + magic) / 8;
    const level = attack < range * 1.5
        ? (2 * defense + 3 * range) / 8 + mage
        : (attack + defense) / 4 + mage;
    return Math.floor(level);
}

/**
 * The lowest combat level these levels can produce — the melee stats pushed to a fresh account's
 * while magic, prayer and ranged stay as asked. A magic-51 account cannot be combat 3, so the
 * slider's minimum moves instead of the panel arguing with the user.
 */
export function minCombatLevel(levels: Levels): number {
    return combatLevelOf({
        ...levels,
        ATTACK: FRESH_LEVEL,
        STRENGTH: FRESH_LEVEL,
        DEFENSE: FRESH_LEVEL,
        HITS: FRESH_HITS,
    });
}

/**
 * {@code levels} with attack/strength/defense/hits chosen so the combat level is {@code target} (or
 * as close as the formula allows from below). Raises defense and hitpoints together — the tankiest
 * reading of "this is how strong I am", and the one that leaves attack low for a magic pure.
 *
 * <p>Never lowers a gated skill: magic, prayer and ranged are inputs in their own right.
 */
export function statsForCombatLevel(levels: Levels, target: number): Levels {
    const floor = minCombatLevel(levels);
    const out: Levels = {
        ...levels,
        ATTACK: FRESH_LEVEL,
        STRENGTH: FRESH_LEVEL,
        DEFENSE: FRESH_LEVEL,
        HITS: FRESH_HITS,
    };
    if (target <= floor) return out;
    // Each defense+hits pair is worth half a combat level ((def + hits) / 4), so walk them up
    // together until the formula reaches the target.
    for (let i = 0; i < 99 && combatLevelOf(out) < target; i++) {
        if (out.DEFENSE < 99) out.DEFENSE += 1;
        if (combatLevelOf(out) >= target) break;
        if (out.HITS < 99) out.HITS += 1;
        if (out.DEFENSE >= 99 && out.HITS >= 99) break;
    }
    return out;
}

/** The thresholds a slider snaps to: the gate breakpoints, plus 1 so "nothing" is reachable. */
export function sliderStops(bps: PlannerThreshold[]): number[] {
    // 1 and 99 are always offered: the level everyone starts at and the one a maxed account sits
    // at. Neither is a gate — nothing a gate asks changes above the top threshold — so they snap
    // and tick like the rest without pretending to open anything.
    const stops = new Set<number>([FRESH_LEVEL, SKILL_MAX]);
    for (const b of bps) stops.add(b.at);
    return [...stops].sort((a, b) => a - b);
}

/**
 * The declared threshold NEAREST `value` — what a drag lands on. Levels between thresholds change
 * nothing a gate reads, so the slider stops where the answers do; the scale stays the full 1–99 so
 * rows compare, and the stretches that decide nothing are dimmed rather than removed.
 */
export function snapNearest(value: number, stops: number[]): number {
    let best = stops[0] ?? value;
    for (const s of stops) {
        if (Math.abs(s - value) < Math.abs(best - value)) best = s;
    }
    return best;
}

/** The stop at or below `value` — what the account's level actually buys. */
export function snapDown(value: number, stops: number[]): number {
    let out = stops[0] ?? FRESH_LEVEL;
    for (const s of stops) if (s <= value) out = s;
    return out;
}

/** Every skill slider runs the full 1–99, so levels are compared across rows at a glance. */
export const SKILL_MIN = 1;
export const SKILL_MAX = 99;

/** The next stop above `value`, or null when it is already at the top. */
export function nextStop(value: number, stops: number[]): number | null {
    for (const s of stops) if (s > value) return s;
    return null;
}

/** An account's levels as the plan request wants them, with the combat stats synthesized. */
export function requestLevels(gateLevels: Levels, combatLevel: number): Levels {
    return statsForCombatLevel(gateLevels, combatLevel);
}
