import {useCallback, useEffect, useState} from "react";
import type {PlannerHost, PlannerInputs, PlanResponse} from "./plannerApi";
import {freshState, maxedState, type PlannerRequestState, toPlanRequest} from "./PlannerPanel";
import {SupersededError} from "./wasmPlannerHost";

export interface Tile {
    x: number;
    z: number;
}

/** Which endpoint the next map click sets, and whether it chains start → end. */
export interface PlannerPick {
    which: "start" | "end";
    chain: boolean;
}

/**
 * One planner's state, for an embedder with nothing else competing for map clicks: the catalogue,
 * the editor, the two endpoints and which one a click sets, and the plan — asked afresh whenever the
 * endpoints or anything the editor holds changes, so there is no "compute" button to hunt for.
 *
 * A click lands only on an ARMED endpoint: "pick" arms the start and chains to the end, a click on
 * an endpoint's field arms just that one. With nothing armed a click does nothing, so a route in
 * hand is never lost to a stray click.
 */
export function usePlannerSession(host: PlannerHost | null) {
    const [inputs, setInputs] = useState<PlannerInputs | null>(null);
    const [state, setState] = useState<PlannerRequestState>(() => freshState(null));
    const [start, setStart] = useState<Tile | null>(null);
    const [end, setEnd] = useState<Tile | null>(null);
    const [pick, setPick] = useState<PlannerPick | null>({which: "start", chain: true});
    const [plan, setPlan] = useState<PlanResponse | null>(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [nonce, setNonce] = useState(0);

    useEffect(() => {
        if (!host) return;
        let alive = true;
        host.inputs().then(
            (i) => {
                if (!alive) return;
                setInputs(i);
                // The default rows and fresh levels come from the declarations.
                setState(freshState(i));
            },
            (e) => alive && setError(e instanceof Error ? e.message : String(e)),
        );
        return () => {
            alive = false;
        };
    }, [host]);

    useEffect(() => {
        if (!host || !start || !end) {
            setPlan(null);
            return;
        }
        let cancelled = false;
        setLoading(true);
        setError(null);
        host.plan(toPlanRequest(state, inputs, start, end))
            .then((r) => {
                if (cancelled) return;
                setPlan(r);
                setLoading(false);
            }, (e) => {
                // A newer ask replaced this one; its own answer ends the loading.
                if (cancelled || e instanceof SupersededError) return;
                setPlan(null);
                setError(e instanceof Error ? e.message : String(e));
                setLoading(false);
            });
        return () => {
            cancelled = true;
        };
    }, [host, start, end, state, inputs, nonce]);

    const setEndpoint = useCallback((which: "start" | "end", tile: Tile) => {
        if (which === "start") setStart(tile);
        else setEnd(tile);
        setPick((p) => (p && p.which === which ? null : p));
    }, []);

    const armEndpoint = useCallback((which: "start" | "end") => {
        setPick({which, chain: false});
    }, []);

    const tilePicked = useCallback((tile: Tile) => {
        if (!pick) return;
        if (pick.which === "start") setStart(tile);
        else setEnd(tile);
        setPick(pick.chain && pick.which === "start" ? {which: "end", chain: true} : null);
    }, [pick]);

    /** Drop the route and arm the start again. */
    const clear = useCallback(() => {
        setStart(null);
        setEnd(null);
        setPlan(null);
        setError(null);
        setPick({which: "start", chain: true});
    }, []);

    /** The editor from a preset: "fresh" or "maxed". */
    const copyFrom = useCallback((choice: string) => {
        if (choice === "fresh") {
            setState(freshState(inputs));
        } else if (choice === "maxed") {
            setState((s) => maxedState(s, inputs));
        }
    }, [inputs]);

    const replan = useCallback(() => setNonce((n) => n + 1), []);

    return {
        inputs, state, setState, start, end, pick, plan, loading, error,
        setEndpoint, armEndpoint, tilePicked, clear, copyFrom, replan,
    };
}
