import * as THREE from "three";

/**
 * Uploading only the prefix of a batch buffer that a frame actually filled.
 *
 * <p>`attribute.needsUpdate = true` re-uploads the WHOLE typed array.
 * {@link THREE.BufferGeometry#setDrawRange} and {@link THREE.InstancedMesh#count}
 * shrink the *draw*, not the upload — {@code WebGLAttributes.updateBuffer} runs
 * a plain {@code gl.bufferSubData(target, 0, array)} unless the attribute
 * carries update ranges. Every batch here is sized for its worst case (6144
 * entity rings, 4096 ground items, 160-and-doubling quads per appearance
 * strip), so a frame with a handful of live entries was shipping the entire
 * capacity: measured live at 3.6 MB per frame across ~245 calls, of which
 * well under 1% had changed.
 *
 * <p>three merges adjacent ranges and clears them again after the upload, so a
 * single range per attribute per frame is all this needs to be.
 */

/**
 * Mark `[0, used)` of `attr` dirty and nothing else.
 *
 * @param attr the attribute whose leading entries the frame just rewrote
 * @param used number of ELEMENTS written, i.e. items × itemSize — not vertices
 *     and not quads. Zero means "nothing changed"; the attribute is left alone
 *     rather than uploaded empty.
 */
export function uploadPrefix(attr: THREE.BufferAttribute, used: number) {
    if (used <= 0) return;
    attr.clearUpdateRanges();
    attr.addUpdateRange(0, Math.min(used, attr.array.length));
    attr.needsUpdate = true;
}

/**
 * The quad-batch case: `quads` quads have been written into a geometry whose
 * attributes are 4 vertices per quad. Handles the position/uv pair together
 * because they are always written in lockstep.
 */
export function uploadQuads(geo: THREE.BufferGeometry, quads: number,
                            ...names: string[]) {
    for (const name of names) {
        const attr = geo.getAttribute(name) as THREE.BufferAttribute | undefined;
        if (attr) uploadPrefix(attr, quads * 4 * attr.itemSize);
    }
}
