import type {
    ItemNames,
    PlannerAccount,
    PlannerReach,
    PlannerHost,
    PlannerInputs,
    PlanRequest,
    PlanResponse,
} from "./plannerApi";
import type {NavOp, NavProgress, NavReply, NavRequest} from "./navWorker";
import {fetchWorldMeshManifest} from "../api";
import type {BotTick, BotView, ServerTransport, ServerWorld} from "../sim/demoServer";

/** The world as read, and what reading it took. */
export interface NavWorldInfo {
    world: string;
    /** Fetching the module and the snapshot. */
    fetchMs: number;
    unzipMs: number;
    readMs: number;
    totalMs: number;
    /** When it finished, on the worker's clock. */
    doneAt: number;
}

/** What building the pathfinder took. */
export interface NavPathfinderInfo {
    transports: number;
    buildMs: number;
    totalMs: number;
    doneAt: number;
}

/**
 * The route planner's pathfinder, in the page: the engine compiled to WebAssembly, in a worker.
 * Nothing is downloaded until it is first asked for — the world, then the pathfinder over it,
 * which every planner question waits for.
 */
export interface WasmPlannerHost extends PlannerHost {
    /** Build the pathfinder, once; settles when it can plan. */
    pathfinder(): Promise<NavPathfinderInfo>;
    /** Every defined item's display name, for the planner's item search. */
    items(): Promise<ItemNames>;
    /** The ids of every item that may be worn — what the panel's "wear" column is offered for. */
    wearableItems(): Promise<number[]>;
    /** What the page needs to play the server over the world: spawns, definitions, walk graph. */
    serverWorld(): Promise<{world: ServerWorld; steps: Int8Array}>;
    /** Start walking `req` as a bot, a tick at a time ({@link walkTick}); replaces any walk. */
    walkStart(req: PlanRequest): Promise<{viewRadius: number; combatLevel: number}>;
    /** One tick of the walk: what the bot sends, having seen `view`. */
    walkTick(view: BotView): Promise<BotTick>;
    /** The transports as the server executes them — built with the pathfinder. */
    serverTransports(): Promise<ServerTransport[]>;
    /** Follow the load's stages; answers the latest at once. Returns the unsubscribe. */
    onProgress(listener: (stage: string) => void): () => void;
    dispose(): void;
}

/** A plan dropped because a newer one was asked before it started. */
export class SupersededError extends Error {
    constructor() {
        super("superseded by a newer plan");
    }
}

/**
 * Start the worker; the world is read on the first question. Plans are LATEST-WINS: each one takes the better part of a
 * second, and an editor that re-plans on every keystroke would otherwise queue a backlog the page
 * waits out. While one runs, only the newest ask waits behind it; the ones it replaced reject
 * with {@link SupersededError}.
 */
export function wasmPlannerHost(): WasmPlannerHost {
    const worker = new Worker(new URL("./navWorker.ts", import.meta.url), {type: "module"});
    let nextId = 1;
    const waiting = new Map<number, { resolve: (v: unknown) => void; reject: (e: Error) => void }>();
    let stage = "starting";
    const listeners = new Set<(stage: string) => void>();
    // When each stage started, on the worker's clock (the page's is late while it draws), for the
    // breakdown logged when a load finishes.
    let started: { stage: string; at: number }[] = [];
    const logStages = (what: string, doneAt: number) => {
        const parts = started.map((s, i) =>
            `${s.stage} ${Math.round((started[i + 1]?.at ?? doneAt) - s.at)} ms`);
        console.info(`[planner] ${what} — ${parts.join(" · ")}`);
        started = [];
    };
    worker.onmessage = (e: MessageEvent<NavReply | NavProgress>) => {
        if ("progress" in e.data) {
            stage = e.data.progress;
            started.push({stage, at: e.data.at});
            for (const l of listeners) l(stage);
            return;
        }
        const reply = e.data;
        const w = waiting.get(reply.id);
        if (!w) return;
        waiting.delete(reply.id);
        if (reply.ok) w.resolve(reply.value);
        else w.reject(new Error(reply.error));
    };
    const call = <T>(op: NavOp, json?: string, baked?: number, view?: BotView): Promise<T> =>
        new Promise<T>((resolve, reject) => {
            const id = nextId++;
            waiting.set(id, {resolve: resolve as (v: unknown) => void, reject});
            worker.postMessage({id, op, json, baked, view} satisfies NavRequest);
        });

    let loaded: Promise<NavWorldInfo> | null = null;
    const world = () => {
        if (!loaded) {
            // The bake's timestamp versions the engine and world URLs, as it does the mesh's.
            loaded = fetchWorldMeshManifest()
                .then((m) => call<NavWorldInfo>("world", undefined, m.baked));
            loaded.then(
                (info) => logStages(`${info.world} read in ${info.totalMs} ms`, info.doneAt),
                (err) => console.error("[planner] the world did not load:", err),
            );
        }
        return loaded;
    };

    let built: Promise<NavPathfinderInfo> | null = null;
    const pathfinder = () => {
        if (!built) {
            built = world().then(() => call<NavPathfinderInfo>("pathfinder"));
            built.then(
                (info) => logStages(
                    `pathfinder over ${info.transports} transports built in ${info.totalMs} ms`,
                    info.doneAt),
                (err) => console.error("[planner] the pathfinder did not build:", err),
            );
        }
        return built;
    };

    let running = false;
    let pending: { json: string;
        resolve: (r: PlanResponse) => void; reject: (e: Error) => void } | null = null;
    const pump = () => {
        if (running || !pending) return;
        const job = pending;
        pending = null;
        running = true;
        pathfinder()
            .then(() => call<PlanResponse>("plan", job.json))
            .then(job.resolve, job.reject)
            .finally(() => {
                running = false;
                pump();
            });
    };

    return {
        pathfinder,
        items: () => world().then(() => call<ItemNames>("items")),
        wearableItems: () => world().then(() => call<number[]>("wearables")),
        inputs: () => pathfinder().then(() => call<PlannerInputs>("inputs")),
        account: (req: PlanRequest) => pathfinder()
            .then(() => call<PlannerAccount>("account", JSON.stringify(req))),
        reachable: (req: PlanRequest) => pathfinder()
            .then(() => call<PlannerReach>("reachable", JSON.stringify(req))),
        plan: (req: PlanRequest) => new Promise<PlanResponse>((resolve, reject) => {
            pending?.reject(new SupersededError());
            pending = {json: JSON.stringify(req), resolve, reject};
            pump();
        }),
        serverWorld: () => world()
            .then(() => call<{world: ServerWorld; steps: Int8Array}>("serverWorld")),
        walkStart: (req: PlanRequest) => pathfinder()
            .then(() => call<{viewRadius: number; combatLevel: number}>(
                "walkStart", JSON.stringify(req))),
        walkTick: (view: BotView) => call<BotTick>("walkTick", undefined, undefined, view),
        serverTransports: () => pathfinder()
            .then(() => call<ServerTransport[]>("serverTransports")),
        onProgress: (listener) => {
            listeners.add(listener);
            listener(stage);
            return () => {
                listeners.delete(listener);
            };
        },
        dispose: () => {
            worker.terminate();
            for (const w of waiting.values()) w.reject(new Error("planner closed"));
            waiting.clear();
        },
    };
}
