import * as THREE from "three";

/**
 * Pooled DOM labels anchored to world points — nameplates, countdowns, chips.
 *
 * Every overlay that wants text over a tile needs the same six things: project the point with a
 * CURRENT camera matrix, cull it when it leaves the screen or falls behind the lens, reuse a div
 * rather than churning one per frame, write only what changed, position without touching layout,
 * and drop the divs nothing claimed this frame. Written out longhand at each call site those six
 * drift apart, so they live here once.
 *
 * Positioning is a single `transform` (not a layout input at all), with
 * the tag's own anchoring folded into the same transform — both parts are pure translations, so
 * composing them in either order lands in the same place. The frame's view size is passed in,
 * measured once at the top of the frame where last frame's layout is still clean.
 */

/**
 * Stacking bands, as z-index. Tags are absolutely positioned siblings, so their order is z-index
 * and nothing else; naming the bands keeps a new overlay from having to guess a number that
 * happens to beat the nameplates.
 *
 * The DOM half of the same idea as `OVERLAY_BAND`, which orders what an overlay draws in the
 * scene. Same word on purpose — a label and an outline of the same thing should be describable
 * with one vocabulary, even though one resolves to a z-index and the other to a renderOrder.
 */
export const TAG_BAND = {
    /** Labels on world features — spawn countdowns, zone names. Under entity plates. */
    world: 880000,
    /** Labels on entities — nameplates, health bars, hit splats. */
    entity: 890000,
    /** Interactive chrome floated over both — chips, handles. */
    chrome: 905000,
} as const;

export type TagBand = keyof typeof TAG_BAND;

export interface TagStyle {
    /** CSS applied once when a tag's div is created. Position, transform and z-index are supplied
     *  by the pool and must not appear here. */
    css: string;
    /** Stacking band. Defaults to `world`. */
    band?: TagBand;
    /** Pixels to lift the tag above its world point — a nameplate clears the head it names. */
    offsetY?: number;
    /** Where the tag sits relative to its (offset) point. `above` puts its bottom edge there,
     *  `centre` centres it. Defaults to `above`. */
    anchor?: "above" | "centre";
    /**
     * Take pointer events, so this pool's tags can be clicked — see {@link TagPool.onClick}.
     *
     * A press still starts a camera drag, so dragging off a tag pans exactly like dragging off
     * anything else; what an interactive tag consumes is the CLICK, which no longer reaches the
     * world under it. Worth it for a small label, not for anything large. The default is false.
     */
    interactive?: boolean;
    /** data-* attributes to stamp on each div (hit-testing by attribute). */
    dataset?: Record<string, string>;
}

/** The frame's screen size in CSS pixels, measured once by the caller before anything writes a
 *  style — see the note above on why it is passed in rather than read here. */
export interface ViewSize {
    w: number;
    h: number;
}

/**
 * A tag whose content is more than a line of text: built into the div by `build`, and rebuilt only
 * when `stamp` changes — so a label with rows and links costs nothing on the frames it stands still.
 */
export interface TagContent {
    stamp: string;
    build(div: HTMLDivElement): void;
}

/** Live interactive pools, by the id stamped on their divs — see {@link resolveTagClick}. */
const interactivePools = new Map<string, TagPool>();
let nextPoolId = 0;

/**
 * The pool and key of the interactive tag under an event target, or null.
 *
 * Resolved at POINTER-DOWN, not from a click: the view takes pointer capture when a drag starts,
 * which retargets every later event — the click included — away from the div and onto the view.
 * A tag that owned a click handler would therefore never hear one. So the press records what it
 * landed on, the drag pans the camera as usual, and only a release that stayed within the click
 * threshold fires it. Pools with no `onClick` never match, so a tag the view handles itself (the
 * transport chip) isn't intercepted here.
 */
export function resolveTagClick(target: EventTarget | null):
    {pool: TagPool; key: string} | null {
    const el = (target as HTMLElement | null)?.closest?.("[data-tag-pool]") as
        HTMLElement | null;
    const pool = el && interactivePools.get(el.dataset.tagPool ?? "");
    const key = el?.dataset.tagKey;
    return pool && pool.onClick && key != null ? {pool, key} : null;
}

/**
 * One pool of same-styled tags, keyed by whatever identity keeps a tag on its subject across
 * frames — a username for something that moves, a tile for something that doesn't.
 *
 * Usage is begin / put per visible tag / end; anything not `put` this frame is removed by `end`.
 */
export class TagPool {
    private readonly divs = new Map<string, HTMLDivElement>();
    private readonly used = new Set<string>();
    private view: ViewSize = {w: 0, h: 0};
    private camera: THREE.Camera | null = null;
    private readonly ndc = new THREE.Vector3();
    /**
     * Set to receive clicks on an interactive pool's tags. A click is a press and release on the
     * tag that stayed within the view's click threshold — dragging off it pans the camera like any
     * other press on the world, and the world pick that a release would otherwise produce is
     * suppressed, so a label click doesn't also select the ground behind it.
     */
    onClick: ((key: string, ev: MouseEvent) => void) | null = null;
    private readonly id = String(nextPoolId++);

    constructor(private readonly host: HTMLElement, private readonly style: TagStyle) {
        if (style.interactive) interactivePools.set(this.id, this);
    }

    /** Open a frame. The camera's world matrix is refreshed here rather than per tag: projecting
     *  against last frame's matrix flings tags around while the camera orbits. */
    begin(view: ViewSize, camera: THREE.Camera): void {
        this.view = view;
        this.camera = camera;
        camera.updateMatrixWorld();
        this.used.clear();
    }

    /**
     * Place one tag at a world point. Returns its div, or null when the point is off-screen or
     * behind the lens — a point behind the camera projects with flipped x/y and would otherwise
     * teleport the tag to a bogus spot mid-rotation.
     */
    put(key: string, at: THREE.Vector3, text: string | TagContent): HTMLDivElement | null {
        if (!this.camera) return null;
        const v = this.ndc.copy(at).project(this.camera);
        if (v.z > 1 || v.z < -1 || v.x < -1.05 || v.x > 1.05 || v.y < -1.05 || v.y > 1.05) {
            return null;
        }
        this.used.add(key);
        let div = this.divs.get(key);
        if (!div) {
            div = document.createElement("div");
            div.style.cssText = "position:absolute;left:0;top:0;white-space:nowrap;"
                + `z-index:${TAG_BAND[this.style.band ?? "world"]};`
                + (this.style.interactive
                    ? "pointer-events:auto;cursor:pointer;"
                    : "pointer-events:none;")
                + this.style.css;
            for (const [k, val] of Object.entries(this.style.dataset ?? {})) {
                div.dataset[k] = val;
            }
            if (this.style.interactive) {
                // Identity for the press, not a handler: see resolveTagClick.
                div.dataset.tagPool = this.id;
                div.dataset.tagKey = key;
            }
            this.host.appendChild(div);
            this.divs.set(key, div);
        }
        if (typeof text === "string") {
            if (div.dataset.stamp !== undefined) delete div.dataset.stamp;
            if (div.textContent !== text) div.textContent = text;
        } else if (div.dataset.stamp !== text.stamp) {
            div.replaceChildren();
            text.build(div);
            div.dataset.stamp = text.stamp;
        }
        const px = ((v.x + 1) / 2) * this.view.w;
        const py = ((1 - v.y) / 2) * this.view.h - (this.style.offsetY ?? 0);
        // One transform: translate to the point, then the tag's own anchoring. Never left/top —
        // those are layout inputs, and moving a few hundred of them per frame is a relayout.
        const self = this.style.anchor === "centre" ? "translate(-50%,-50%)" : "translate(-50%,-100%)";
        const t = `translate(${px}px,${py}px) ${self}`;
        if (div.style.transform !== t) div.style.transform = t;
        return div;
    }

    /** The live div for a key, or null when nothing is showing it. For the odd caller that has to
     *  ask the DOM something about a tag — whether the cursor is over it, say. */
    get(key: string): HTMLDivElement | null {
        return this.divs.get(key) ?? null;
    }

    /** Close the frame: drop every tag nothing claimed. */
    end(): void {
        for (const [key, div] of this.divs) {
            if (!this.used.has(key)) {
                div.remove();
                this.divs.delete(key);
            }
        }
        this.camera = null;
    }

    /** Remove every tag (a wholesale reset, like a floor switch). The pool stays usable. */
    clear(): void {
        for (const div of this.divs.values()) div.remove();
        this.divs.clear();
        this.used.clear();
    }

    /** Teardown: clear, and stop answering {@link resolveTagClick}. */
    dispose(): void {
        this.clear();
        interactivePools.delete(this.id);
    }
}
