import type {RoutePoint} from "../api";
import type {EnginePlanStep} from "./plannerApi";

/**
 * The engine's own route as points to drape: the start tile, then each seam span's middle, each
 * hop's entry and landing (the landing a jump, so the line breaks there), each booth, and the
 * destination's centre. What the dotted line beside the simulated walk is drawn from: the walk
 * follows this where the walker honours the danger field and cuts off it where it can see.
 */
export function enginePlanPoints(start: {x: number; z: number} | null,
                                 plan: EnginePlanStep[] | null | undefined): RoutePoint[] | null {
    if (!plan || plan.length === 0) return null;
    const out: RoutePoint[] = [];
    if (start) out.push({x: start.x, z: start.z, hop: false});
    for (const s of plan) {
        switch (s.type) {
            case "cross":
            case "arrive":
                out.push({
                    x: Math.round((s.x + (s.x2 ?? s.x)) / 2),
                    z: Math.round((s.z + (s.z2 ?? s.z)) / 2),
                    hop: false,
                });
                break;
            case "hop":
                out.push({x: s.x, z: s.z, hop: false});
                out.push({x: s.x2 ?? s.x, z: s.z2 ?? s.z, hop: true});
                break;
            case "bank":
                out.push({x: s.x, z: s.z, hop: false});
                break;
        }
    }
    return out;
}
