import {useEffect, useMemo, useRef} from "react";
import type {PlannerInputs} from "./plannerApi";
import {freshState, type PlannerRequestState, policyOf} from "./PlannerPanel";
import type {Tile} from "./usePlannerSession";

/**
 * The route planner in the URL — `?plan=…` — so a link shows the next person what you see: the
 * editor as you filled it, the two endpoints, and the account it plans as. Present exactly while
 * the panel is open; removed when it closes.
 *
 * The value is the share as JSON, base64url-encoded: opaque but stable, a couple of kilobytes at
 * most, and readable by both hosts (the runner and the static demo) through this one module. The
 * other params (`tab`, `floor`, the camera) belong to the hosts and are merged around, never
 * rewritten — the same courtesy their own writers extend.
 */

/** What a shared link carries. `v` guards the shape: a link from another version restores nothing
 *  rather than something half-right. */
export interface PlannerShare {
    v: 1;
    from: Tile | null;
    to: Tile | null;
    /** The account planned as, where the host plans as one (the runner's walk tool). */
    as: string | null;
    state: PlannerRequestState;
}

export const PLAN_PARAM = "plan";

export function encodePlannerShare(share: PlannerShare): string {
    const bytes = new TextEncoder().encode(JSON.stringify(share));
    let bin = "";
    for (const b of bytes) bin += String.fromCharCode(b);
    return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

/** The share `s` encodes, or null for anything that is not one — a truncated paste, an older
 *  version, hand-edited nonsense. */
export function decodePlannerShare(s: string): PlannerShare | null {
    try {
        const b64 = s.replace(/-/g, "+").replace(/_/g, "/");
        const bin = atob(b64 + "=".repeat((4 - b64.length % 4) % 4));
        const bytes = Uint8Array.from(bin, c => c.charCodeAt(0));
        const v: unknown = JSON.parse(new TextDecoder().decode(bytes));
        if (!isObject(v) || v.v !== 1 || !isObject(v.state)) return null;
        const state = v.state;
        if (!isObject(state.levels) || !Array.isArray(state.rows) || !isObject(state.policy)) {
            return null;
        }
        return {
            v: 1,
            from: tile(v.from),
            to: tile(v.to),
            as: typeof v.as === "string" ? v.as : null,
            state: state as unknown as PlannerRequestState,
        };
    } catch {
        return null;
    }
}

/** The share the page was opened with, or null. */
export function readPlannerShare(): PlannerShare | null {
    const raw = new URLSearchParams(location.search).get(PLAN_PARAM);
    return raw ? decodePlannerShare(raw) : null;
}

/** Put `share` in the URL (null removes it), leaving every other param as it is. Replaces the
 *  history entry: each keystroke in the editor is not a page the back button should revisit. */
export function writePlannerShare(share: PlannerShare | null): void {
    const p = new URLSearchParams(location.search);
    const next = share ? encodePlannerShare(share) : null;
    if (p.get(PLAN_PARAM) === next) return;
    if (next) p.set(PLAN_PARAM, next);
    else p.delete(PLAN_PARAM);
    const query = p.toString();
    history.replaceState(null, "", `${location.pathname}${query ? "?" + query : ""}${location.hash}`);
}

export interface PlannerUrlSyncArgs {
    open: boolean;
    setOpen: (open: boolean) => void;
    /** The catalogue. Restoring waits for it: its arrival is what resets the editor to fresh, and
     *  a restore before it would be overwritten by that. */
    inputs: PlannerInputs | null;
    state: PlannerRequestState;
    setState: (state: PlannerRequestState) => void;
    start: Tile | null;
    end: Tile | null;
    setEndpoint: (which: "start" | "end", tile: Tile) => void;
    as?: string | null;
    setAs?: (as: string | null) => void;
}

/**
 * Keep the planner and `?plan=` in step: a share in the URL at load opens the panel and fills it
 * once the catalogue has landed; while the panel is open every change rewrites the param; closing
 * it removes the param. Nothing is written until a pending restore has been applied, so the
 * fresh editor never overwrites the link the page was opened with.
 */
export function usePlannerUrlSync(args: PlannerUrlSyncArgs): void {
    const {open, setOpen, inputs, state, setState, start, end, setEndpoint, as, setAs} = args;
    const shared = useMemo(() => readPlannerShare(), []);
    const restored = useRef(shared == null);
    useEffect(() => {
        if (shared) setOpen(true);
        // Once, at load — the share is read once too.
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);
    useEffect(() => {
        if (restored.current || !shared || !inputs) return;
        restored.current = true;
        // Spread over a fresh editor, so a key this version added still gets its default.
        setState({...freshState(inputs), ...shared.state, policy: policyOf(shared.state.policy)});
        if (shared.from) setEndpoint("start", shared.from);
        if (shared.to) setEndpoint("end", shared.to);
        // After the endpoints: a host that clears "plan as" when an endpoint is set must not clear
        // the one the link carried.
        if (setAs && shared.as != null) setAs(shared.as);
    }, [shared, inputs, setState, setEndpoint, setAs]);
    useEffect(() => {
        if (!open) {
            writePlannerShare(null);
            return;
        }
        if (!restored.current || !inputs) return;
        writePlannerShare({v: 1, from: start, to: end, as: as ?? null, state});
    }, [open, inputs, state, start, end, as]);
}

function isObject(v: unknown): v is Record<string, unknown> {
    return typeof v === "object" && v !== null && !Array.isArray(v);
}

function tile(v: unknown): Tile | null {
    return isObject(v) && typeof v.x === "number" && typeof v.z === "number"
        ? {x: v.x, z: v.z} : null;
}
