import * as THREE from "three";
import {asset, versioned} from "./api";

/**
 * The per-layer player atlas: every wearable sprite reduced to recolour-neutral
 * pixels, with the alpha byte tagging WHICH recolour each pixel takes — 0xFF
 * already final, 0xFE/FD/FC hair/top/bottom, 0xFB skin, 0x00 empty.
 *
 * <p>That tagging is exactly a fragment shader's input, so nothing here is
 * composited. {@link import("./World3DPlayerSprites")} binds this one texture,
 * draws a quad per worn layer, and lets the GPU apply the palette — which is
 * what both reference clients do: the stock Java client recolours per pixel
 * inside its blit kernel (surface.spriteClipping… → plot_trans_scale_with_2_masks)
 * and rsc-c's GL renderer does it in one multiply-add
 * ({@code fragment_colour = texture_colour * vertex_colour + base_texture_colour},
 * cache/flat.fs). Neither ever builds a per-appearance strip.
 */

/** ax, ay, w, h, dx, dy — see {@link cropIndex}. */
export const CROP_STRIDE = 6;
const ORDERS = 10;   // 8 walk facings + combat stance A/B
const WALKS = 3;
const CLASSES = 3;   // slot class 0, 3 (shield-ish), 4 (weapon-ish)

export interface PlayerLayerAtlas {
    tex: THREE.Texture;
    atlasW: number;
    atlasH: number;
    /** Atlas px per world unit. */
    scale: number;
    originX: number;
    originY: number;
    width1: number;
    height: number;
    /** [facing row][12] — the back-to-front slot order for that facing. */
    layerOrder: number[][];
    palettes: {hair: number[]; clothing: number[]; skin: number[]};
    /**
     * Flat crop table, {@link CROP_STRIDE} entries per (anim, class, order,
     * walk). ax < 0 means "this layer draws nothing in this frame".
     *
     * <p>Flat and integer-indexed on purpose: the draw loop resolves twelve of
     * these per player per frame, and the shape it replaces
     * ({@code crops[animId][slotClass][`${order},${walk}`]}) cost a string
     * concatenation and three hash lookups every time.
     */
    crops: Int16Array;
    maxAnim: number;
}

export function cropIndex(animId: number, slotClass: number,
                          order: number, walk: number): number {
    return ((((animId * CLASSES) + slotClass) * ORDERS + order) * WALKS + walk)
        * CROP_STRIDE;
}

/** Slot -> the crop table's class dimension (the atlas keys these "0"/"3"/"4"). */
export function classOfSlot(slot: number): number {
    return slot === 3 ? 1 : slot === 4 ? 2 : 0;
}

interface AtlasIndexJson {
    baked?: number;
    scale: number;
    originX: number;
    originY: number;
    width1: number;
    height: number;
    atlasW: number;
    atlasH: number;
    palettes: {hair: number[]; clothing: number[]; skin: number[]};
    layerOrder: number[][];
    atlas: [number, number, number, number][];
    crops: Record<string, Record<string, Record<string, [number, number, number]>>>;
}

let pending: Promise<PlayerLayerAtlas> | null = null;

export function loadPlayerLayerAtlas(): Promise<PlayerLayerAtlas> {
    if (pending) return pending;
    pending = (async () => {
        const idx: AtlasIndexJson =
            await fetch(await versioned("/api/world3d/player-layers/index.json"))
                .then(r => {
                    if (!r.ok) throw new Error(`atlas index ${r.status}`);
                    return r.json();
                });
        // ?v= from the bake stamp (see ItemAtlas.pngUrl for the failure mode).
        const blob = await fetch(asset("/api/world3d/player-layers/atlas.png"
            + (idx.baked != null ? `?v=${idx.baked}` : ""))).then(r => r.blob());
        // The alpha byte is a TAG, not coverage, and the RGB is a shade ramp,
        // not a colour — so nothing may touch either. No premultiply, and no
        // colour-profile conversion on decode.
        const bmp = await createImageBitmap(blob, {
            premultiplyAlpha: "none",
            colorSpaceConversion: "none",
        });
        const tex = new THREE.Texture(bmp);
        tex.magFilter = THREE.NearestFilter;
        tex.minFilter = THREE.NearestFilter;
        tex.generateMipmaps = false;
        tex.flipY = false;
        tex.premultiplyAlpha = false;
        // NoColorSpace: the shader below writes its result straight out, the
        // way the raw world materials do, so decode and encode both stay off
        // and a pixel lands on screen as the exact byte the bake produced.
        tex.colorSpace = THREE.NoColorSpace;
        tex.needsUpdate = true;

        let maxAnim = 0;
        for (const k of Object.keys(idx.crops)) {
            const n = parseInt(k, 10);
            if (n > maxAnim) maxAnim = n;
        }
        const crops = new Int16Array(
            (maxAnim + 1) * CLASSES * ORDERS * WALKS * CROP_STRIDE).fill(-1);
        for (const [animKey, byClass] of Object.entries(idx.crops)) {
            const animId = parseInt(animKey, 10);
            for (let cls = 0; cls < CLASSES; cls++) {
                // A slot class with no entry for a frame falls back to class "0";
                // bake that in here rather than testing it per draw.
                const table = byClass[cls === 1 ? "3" : cls === 2 ? "4" : "0"]
                    ?? byClass["0"];
                const fallback = byClass["0"];
                for (let order = 0; order < ORDERS; order++) {
                    for (let walk = 0; walk < WALKS; walk++) {
                        const fk = `${order},${walk}`;
                        const c = table?.[fk] ?? fallback?.[fk];
                        if (!c) continue;
                        const [uid, dx, dy] = c;
                        const tile = idx.atlas[uid];
                        if (!tile) continue;
                        const at = cropIndex(animId, cls, order, walk);
                        crops[at] = tile[0];
                        crops[at + 1] = tile[1];
                        crops[at + 2] = tile[2];
                        crops[at + 3] = tile[3];
                        crops[at + 4] = dx;
                        crops[at + 5] = dy;
                    }
                }
            }
        }
        return {
            tex, atlasW: idx.atlasW, atlasH: idx.atlasH, scale: idx.scale,
            originX: idx.originX, originY: idx.originY, width1: idx.width1,
            height: idx.height, layerOrder: idx.layerOrder,
            palettes: idx.palettes, crops, maxAnim,
        };
    })();
    return pending;
}

/** Clamp into a palette exactly as the engine kernel does. */
export function palClamp(table: number[], i: number): number {
    return Math.max(0, Math.min(table.length - 1, i | 0));
}
