import {useEffect, useState, type Dispatch, type SetStateAction} from "react";

/**
 * `useState` whose value outlives the component: read from `localStorage[key]` on first render,
 * written back on every change. For small per-browser conveniences — a calculator's inputs, a
 * remembered filter — on views that are unmounted when the user switches tabs.
 *
 * Storage failures (private mode, quota, a parse error on a stale shape) fall back to `initial`
 * silently; the value is a convenience, never something the page depends on. When the stored
 * value and `initial` are both plain objects the stored one is spread over `initial`, so a key
 * added later still gets its default rather than `undefined`.
 */
export function useStoredState<T>(key: string, initial: T): [T, Dispatch<SetStateAction<T>>] {
    const [value, setValue] = useState<T>(() => {
        try {
            const raw = localStorage.getItem(key);
            if (raw == null) return initial;
            const parsed: unknown = JSON.parse(raw);
            if (isPlainObject(initial) && isPlainObject(parsed)) {
                return {...(initial as object), ...(parsed as object)} as T;
            }
            return parsed as T;
        } catch {
            return initial;
        }
    });
    useEffect(() => {
        try {
            localStorage.setItem(key, JSON.stringify(value));
        } catch {
            // nothing to do — the in-memory value still works for this session
        }
    }, [key, value]);
    return [value, setValue];
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
    return typeof v === "object" && v !== null && !Array.isArray(v);
}
